getWikiPagePdfUrl(pageId: number): string {
  return `${this.baseUrl}/api/wiki/pages/${pageId}/pdf`
}

getWikiPageMarkdownUrl(pageId: number): string {
  return `${this.baseUrl}/api/wiki/pages/${pageId}/markdown`
}

async downloadWikiPagePdf(pageId: number): Promise<void> {
  const url = this.getWikiPagePdfUrl(pageId)
  const res = await fetch(url, { headers: this.getAuthHeaders() })
  if (!res.ok) throw new Error(`PDF download failed: ${res.status}`)
  const blob = await res.blob()
  const a = document.createElement('a')
  a.href = URL.createObjectURL(blob)
  a.download = res.headers.get('Content-Disposition')?.match(/filename="(.+)"/)?.[1] || 'wiki-page.pdf'
  a.click()
  URL.revokeObjectURL(a.href)
}

