// Import generated types from OpenAPI spec
import type { components, operations } from './api.types'

// Re-export types for convenience
export type User = components['schemas']['User']
export type AuthResponse = components['schemas']['AuthResponse']
export type SignupRequest = components['schemas']['SignupRequest']
export type LoginRequest = components['schemas']['LoginRequest']
export type Project = components['schemas']['Project']
export type Task = components['schemas']['Task'] & { task_number?: number; github_issue_number?: number | null; github_repo?: string; start_date?: string | null; github_reactions?: GitHubReaction[]; agent_name?: string | null }
export type ApiError = components['schemas']['Error']

export interface GitHubReaction {
  reaction: string
  count: number
  user_reacted?: boolean
}

// Types with required fields for commonly used API responses
export interface TaskComment {
  id: number
  task_id: number
  user_id: number
  user_name?: string | null
  agent_name?: string | null
  comment: string
  created_at: string
  updated_at: string
  github_reactions?: GitHubReaction[]
}

export interface ActivityEntry {
  id: number
  project_id: number
  user_id: number
  user_name?: string
  action: string
  entity_type: string
  entity_id: number
  entity_title?: string
  details?: Record<string, unknown>
  created_at: string
}

export interface Sprint {
  id: number
  user_id: number
  name: string
  start_date?: string
  end_date?: string
  goal: string
  status: string
  is_shared?: boolean
  created_at: string
  updated_at?: string
}

export interface Tag {
  id: number
  user_id: number
  name: string
  color: string
  is_shared?: boolean
  created_at: string
}

export interface Attachment {
  id: number
  task_id: number
  filename: string
  alt_name?: string
  file_type: string
  content_type: string
  file_size: number
  cloudinary_url: string
  cloudinary_public_id: string
  created_at: string
}

export interface WikiPageAttachment {
  id: number
  wiki_page_id: number
  project_id: number
  user_id: number
  filename: string
  alt_name?: string
  file_type: string
  content_type: string
  file_size: number
  cloudinary_url: string
  cloudinary_public_id: string
  created_at: string
  user_name?: string | null
}

export interface Invite {
  id: number
  code: string
  inviter_id: number
  invitee_id?: number
  invitee_name?: string
  used_at?: string
  expires_at?: string
  created_at: string
}

export interface ProjectMember {
  id: number
  user_id: number
  email: string
  name?: string
  user_name?: string
  role: string
  granted_by: number
  granted_at: string
}

export interface ProjectInvitation {
  id: number
