              style="flex:1;padding:6px 10px;border:1px solid #ddd;border-radius:6px;font-size:.85rem;background:#f8f8f8;" />
            <button class="modal-btn modal-btn-primary share-copy-btn" data-target="share-collab-url">Copy</button>
