        #opacity-val { display:none; }
        #sidebar .sb-action[data-action="copy-link"] { display:none; }
      }
    `;
    document.head.appendChild(s);
  }

  // ── Resize ────────────────────────────────────────────────────────────────
  function resizeCanvas() {
    const wrap = canvas.parentElement;
    canvas.width = wrap.clientWidth;
    canvas.height = wrap.clientHeight;
  }

  // ── Coordinate helpers ────────────────────────────────────────────────────
  function canvasToWorld(cx, cy) {
    return {
      x: (cx - vp.x) / vp.scale,
      y: (cy - vp.y) / vp.scale,
    };
  }

  function getMousePos(e) {
    const rect = canvas.getBoundingClientRect();
    return {
      cx: e.clientX - rect.left,
      cy: e.clientY - rect.top,
    };
  }

  // ── Roughness helpers ─────────────────────────────────────────────────────
  function hashCode(str) {
    let h = 0;
    for (let i = 0; i < str.length; i++) {
      h = ((h << 5) - h) + str.charCodeAt(i);
      h |= 0;
    }
    return Math.abs(h) || 1;
  }

  function seededRandom(seed) {
    let s = seed | 0;
    return function () {
      s = (s + 0x6D2B79F5) | 0;
      let t = Math.imul(s ^ (s >>> 15), 1 | s);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function roughLine(ctx, x1, y1, x2, y2, rough, rng) {
    const len = Math.hypot(x2 - x1, y2 - y1);
    if (len < 0.1) return;
    const amp = rough * Math.min(len * 0.05, 3.5);
    const dx = x2 - x1, dy = y2 - y1;
    const nx = -dy / len, ny = dx / len;
    const cpx = (x1 + x2) / 2 + nx * (rng() - 0.5) * amp * 2;
    const cpy = (y1 + y2) / 2 + ny * (rng() - 0.5) * amp * 2;
    ctx.moveTo(x1 + (rng() - 0.5) * amp * 0.5, y1 + (rng() - 0.5) * amp * 0.5);
    ctx.quadraticCurveTo(cpx, cpy, x2 + (rng() - 0.5) * amp * 0.5, y2 + (rng() - 0.5) * amp * 0.5);
  }

  function roughEllipse(ctx, cx, cy, rx, ry, rough, rng) {
    const steps = 32;
    const maxR = Math.max(rx, ry);
    const amp = rough * Math.min(maxR * 0.03, 2.5);
    const sx = cx + (rx + (rng() - 0.5) * amp * 1.5);
    const sy = cy + (rng() - 0.5) * amp * 0.8;
    ctx.moveTo(sx, sy);
    for (let i = 1; i <= steps; i++) {
      const a = (i / steps) * Math.PI * 2;
      const x = cx + Math.cos(a) * (rx + (rng() - 0.5) * amp * 1.5);
      const y = cy + Math.sin(a) * (ry + (rng() - 0.5) * amp * 1.5);
      const pa = ((i - 0.5) / steps) * Math.PI * 2;
      const cpx = cx + Math.cos(pa) * (rx + (rng() - 0.5) * amp * 1.8);
      const cpy = cy + Math.sin(pa) * (ry + (rng() - 0.5) * amp * 1.8);
      ctx.quadraticCurveTo(cpx, cpy, x, y);
    }
  }

  // ── Rendering ─────────────────────────────────────────────────────────────
  const GRID_SIZE = 20;

  function render() {
    const W = canvas.width, H = canvas.height;
    ctx.clearRect(0, 0, W, H);

    // Background
    ctx.fillStyle = darkMode ? "#1a1a2e" : "#f8f8f8";
    ctx.fillRect(0, 0, W, H);

    // Dot grid
    const gs = GRID_SIZE * vp.scale;
    const offX = ((vp.x % gs) + gs) % gs;
    const offY = ((vp.y % gs) + gs) % gs;
    ctx.fillStyle = darkMode ? "#3a3a5c" : "#d4d4d8";
    for (let x = offX; x < W; x += gs) {
      for (let y = offY; y < H; y += gs) {
        ctx.beginPath();
        ctx.arc(x, y, 1, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // World transform
    ctx.save();
    ctx.translate(vp.x, vp.y);
    ctx.scale(vp.scale, vp.scale);

    // Draw all elements
    for (const el of scene.elements) {
      drawElement(ctx, el);
    }

    // Current element (being drawn)
    if (currentEl) drawElement(ctx, currentEl);

    // Selection handles
    if (IS_EDIT) {
      // Group selected elements by groupId so a whole library item shows a
      // single combined bounding box instead of one per element.
      const drawnGroups = new Set();
      for (const el of scene.elements) {
        if (!selectedIds.has(el.id)) continue;
        if (el.groupId) {
          if (drawnGroups.has(el.groupId)) continue;
          const groupMembers = scene.elements.filter(e => e.groupId === el.groupId && selectedIds.has(e.id));
          if (groupMembers.length > 1) {
            drawGroupSelection(ctx, groupMembers);
            drawnGroups.add(el.groupId);
            continue;
          }
        }
        drawSelection(ctx, el);
      }
    }

    // Marquee selection rectangle
    if (marquee) {
      ctx.save();
      ctx.fillStyle = "rgba(99, 102, 241, 0.08)";
      ctx.strokeStyle = "#6366f1";
      ctx.lineWidth = 1 / vp.scale;
      ctx.setLineDash([4 / vp.scale, 4 / vp.scale]);
      ctx.fillRect(marquee.x, marquee.y, marquee.w, marquee.h);
      ctx.strokeRect(marquee.x, marquee.y, marquee.w, marquee.h);
      ctx.setLineDash([]);
      ctx.restore();
    }

    ctx.restore();

    // Eraser cursor — drawn in screen space
    if (activeTool === "eraser" && eraserCursorPos) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(eraserCursorPos.cx, eraserCursorPos.cy, ERASER_RADIUS, 0, Math.PI * 2);
      ctx.strokeStyle = "#e03131";
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = 0.7;
      ctx.stroke();
      ctx.restore();
    }

    // Sync sidebar with current state
    if (IS_EDIT) updateSidebar();
  }

  function applyStyle(ctx, el) {
    ctx.strokeStyle = el.strokeColor || "#1e1e2e";
    ctx.fillStyle = el.fillColor || "transparent";
    ctx.lineWidth = el.strokeWidth || 2;
    ctx.lineJoin = "round";
    ctx.lineCap = "round";
    ctx.globalAlpha = (el.opacity ?? 100) / 100;

    // Stroke style (dash pattern)
    const sw = el.strokeWidth || 2;
    switch (el.strokeStyle || "solid") {
      case "dashed": ctx.setLineDash([sw * 4, sw * 3]); break;
      case "dotted": ctx.setLineDash([sw * 0.5, sw * 2.5]); break;
      default: ctx.setLineDash([]); break;
    }
  }

  function drawElement(ctx, el) {
    ctx.save();
    applyStyle(ctx, el);
    // Apply rotation around element center
    const angle = el.angle || 0;
    if (angle) {
      const c = getCenter(el);
      ctx.translate(c.x, c.y);
      ctx.rotate(angle);
      ctx.translate(-c.x, -c.y);
    }
    switch (el.type) {
      case "rect":     drawRect(ctx, el); break;
      case "diamond":  drawDiamond(ctx, el); break;
      case "ellipse":  drawEllipse(ctx, el); break;
      case "line":     drawLine(ctx, el); break;
      case "arrow":    drawArrow(ctx, el); break;
      case "pencil":   drawPencil(ctx, el); break;
      case "text":     drawText(ctx, el); break;
      case "image":    drawImage(ctx, el); break;
    }
    // Render inline text label for shapes
    if (el.text && el.type !== "text") {
      drawShapeText(ctx, el);
    }
    ctx.restore();
  }

  // Cache of CSS-measured metrics per (font-family, size). We probe the real
  // DOM so the canvas text can be positioned to pixel-match an HTML textarea
  // with the same font/line-height.
  const cssFontMetricsCache = new Map();
  function getCssFontMetrics(fontFamily, fs) {
    const key = fontFamily + "|" + fs;
    const cached = cssFontMetricsCache.get(key);
    if (cached) return cached;
    const probe = document.createElement("div");
    probe.style.cssText = `position:absolute;left:-9999px;top:0;visibility:hidden;
      font-size:${fs}px;font-family:${fontCSS(fontFamily)};
      line-height:1.3;white-space:nowrap;margin:0;padding:0;border:0;`;
    // vertical-align:baseline span gives us the baseline Y.
    const baselineSpan = document.createElement("span");
    baselineSpan.style.cssText = `display:inline-block;width:0;height:0;vertical-align:baseline;`;
    probe.appendChild(document.createTextNode("Mg"));
    probe.appendChild(baselineSpan);
    document.body.appendChild(probe);
    const probeRect = probe.getBoundingClientRect();
    const spanRect = baselineSpan.getBoundingClientRect();
    const lineHeight = probeRect.height;
    const baseline = spanRect.top - probeRect.top;
    document.body.removeChild(probe);
    const m = { lineHeight, baseline };
    cssFontMetricsCache.set(key, m);
    return m;
  }

  function drawShapeText(ctx, el) {
    const bb = getBBox(el);
    const fs = el.fontSize || 16;
    const ff = el.fontFamily || "sans-serif";
    ctx.font = `${fs}px ${fontCSS(ff)}`;
    ctx.fillStyle = el.strokeColor || "#1e1e2e";
    ctx.textBaseline = "alphabetic";
    const align = el.textAlign || "center";
    ctx.textAlign = align;
    ctx.setLineDash([]);
    const lines = el.text.split("\n");
    const cssM = getCssFontMetrics(ff, fs);
    const lineHeight = cssM.lineHeight;
    const totalH = lines.length * lineHeight;
    const lineBoxTop = bb.y + bb.h / 2 - totalH / 2;
    const baseline0 = lineBoxTop + cssM.baseline;
    lines.forEach((line, i) => {
      let tx = bb.x + bb.w / 2;
      if (align === "left") tx = bb.x + 8;
      else if (align === "right") tx = bb.x + bb.w - 8;
      ctx.fillText(line, tx, baseline0 + i * lineHeight);
    });
    ctx.textAlign = "start";
  }

  // Hachure fill: draw parallel diagonal lines across the shape, clipped to
  // the shape's path. `crosshatch` adds a second set of lines perpendicular.
  function drawHachureLines(ctx, bb, angle, spacing) {
    const cx = bb.x + bb.w / 2, cy = bb.y + bb.h / 2;
    const diag = Math.hypot(bb.w, bb.h) + spacing;
    const cos = Math.cos(angle), sin = Math.sin(angle);
    for (let d = -diag; d <= diag; d += spacing) {
      const px = cx - sin * d;
      const py = cy + cos * d;
      ctx.beginPath();
      ctx.moveTo(px - cos * diag, py - sin * diag);
      ctx.lineTo(px + cos * diag, py + sin * diag);
      ctx.stroke();
    }
  }
  function fillPatternedPath(ctx, pathFn, bb, fillColor, style) {
    if (!fillColor || fillColor === "transparent") return;
    ctx.save();
    ctx.beginPath();
    pathFn(ctx);
    if (style === "solid") {
      ctx.fillStyle = fillColor;
      ctx.fill();
    } else {
      ctx.clip();
      ctx.strokeStyle = fillColor;
      ctx.lineWidth = 1.2;
      ctx.setLineDash([]);
      ctx.lineCap = "round";
      drawHachureLines(ctx, bb, -Math.PI / 4, 8);
      if (style === "cross-hatch") {
        drawHachureLines(ctx, bb, Math.PI / 4, 8);
      }
    }
    ctx.restore();
  }

  function drawRect(ctx, el) {
    const { x, y, w, h } = el;
    const r = el.roughness ?? 0;
    const rn = el.roundness || "sharp";
    const radius = rn === "round" ? Math.min(Math.abs(w), Math.abs(h)) * 0.15 : 0;

    const bb = { x: Math.min(x, x+w), y: Math.min(y, y+h), w: Math.abs(w), h: Math.abs(h) };
    fillPatternedPath(ctx, (c) => c.roundRect(x, y, w, h, radius), bb, el.fillColor, el.fillStyle || "hachure");

    if (r === 0) {
      // Clean stroke
      ctx.beginPath();
      ctx.roundRect(x, y, w, h, radius);
      ctx.stroke();
    } else {
      // Rough stroke — normalize corners
      const x0 = Math.min(x, x + w), y0 = Math.min(y, y + h);
      const x1 = Math.max(x, x + w), y1 = Math.max(y, y + h);
      const seed = hashCode(el.id);
      for (let pass = 0; pass < 2; pass++) {
        const rng = seededRandom(seed + pass * 1000);
        ctx.beginPath();
        roughLine(ctx, x0, y0, x1, y0, r, rng);
        roughLine(ctx, x1, y0, x1, y1, r, rng);
        roughLine(ctx, x1, y1, x0, y1, r, rng);
        roughLine(ctx, x0, y1, x0, y0, r, rng);
        ctx.stroke();
      }
    }
  }

  function drawDiamond(ctx, el) {
    const { x, y, w, h } = el;
    const r = el.roughness ?? 0;
    const cx = x + w / 2, cy = y + h / 2;

    const bb = { x: Math.min(x, x+w), y: Math.min(y, y+h), w: Math.abs(w), h: Math.abs(h) };
    fillPatternedPath(ctx, (c) => {
      c.moveTo(cx, y); c.lineTo(x + w, cy); c.lineTo(cx, y + h); c.lineTo(x, cy); c.closePath();
    }, bb, el.fillColor, el.fillStyle || "hachure");

    if (r === 0) {
      ctx.beginPath();
      ctx.moveTo(cx, y);
      ctx.lineTo(x + w, cy);
      ctx.lineTo(cx, y + h);
      ctx.lineTo(x, cy);
      ctx.closePath();
      ctx.stroke();
    } else {
      const seed = hashCode(el.id);
      for (let pass = 0; pass < 2; pass++) {
        const rng = seededRandom(seed + pass * 1000);
        ctx.beginPath();
        roughLine(ctx, cx, y, x + w, cy, r, rng);
        roughLine(ctx, x + w, cy, cx, y + h, r, rng);
        roughLine(ctx, cx, y + h, x, cy, r, rng);
        roughLine(ctx, x, cy, cx, y, r, rng);
        ctx.stroke();
      }
    }
  }

  function drawEllipse(ctx, el) {
    const cx = el.x + el.w / 2, cy = el.y + el.h / 2;
    const rx = Math.abs(el.w / 2), ry = Math.abs(el.h / 2);
    const r = el.roughness ?? 0;

    const bb = { x: cx - rx, y: cy - ry, w: rx * 2, h: ry * 2 };
    fillPatternedPath(ctx, (c) => c.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2), bb, el.fillColor, el.fillStyle || "hachure");

    if (r === 0) {
      ctx.beginPath();
      ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
      ctx.stroke();
    } else {
      const seed = hashCode(el.id);
      for (let pass = 0; pass < 2; pass++) {
        const rng = seededRandom(seed + pass * 1000);
        ctx.beginPath();
        roughEllipse(ctx, cx, cy, rx, ry, r, rng);
        ctx.stroke();
      }
    }
  }

  // ── Line curve helpers ───────────────────────────────────────────────
  // Lines/arrows become curved when `el.cp` (control point) is set.
  // Rendered as a quadratic bezier from start → cp → end.
  function lineStartEnd(el) {
    if (el.pts && el.pts.length > 1) {
      return { s: { x: el.pts[0].x, y: el.pts[0].y }, e: { x: el.pts[el.pts.length - 1].x, y: el.pts[el.pts.length - 1].y } };
    }
    return { s: { x: el.x, y: el.y }, e: { x: el.x2, y: el.y2 } };
  }
  function lineMidHandlePos(el) {
    if (el.cp) return { x: el.cp.x, y: el.cp.y };
    const { s, e } = lineStartEnd(el);
    return { x: (s.x + e.x) / 2, y: (s.y + e.y) / 2 };
  }
  function bezierPoint(t, p0, p1, p2) {
    const mt = 1 - t;
    return {
      x: mt * mt * p0.x + 2 * mt * t * p1.x + t * t * p2.x,
      y: mt * mt * p0.y + 2 * mt * t * p1.y + t * t * p2.y,
    };
  }
  function sampleBezier(p0, p1, p2, steps) {
    const out = [p0];
    for (let i = 1; i <= steps; i++) out.push(bezierPoint(i / steps, p0, p1, p2));
    return out;
  }
  function strokeCurvedLine(ctx, el, p0, p2) {
    const r = el.roughness ?? 0;
    const p1 = el.cp;
    if (r === 0) {
      ctx.beginPath();
      ctx.moveTo(p0.x, p0.y);
      ctx.quadraticCurveTo(p1.x, p1.y, p2.x, p2.y);
      ctx.stroke();
      return;
    }
    // Sample the curve into short segments and draw them as rough lines.
    const pts = sampleBezier(p0, p1, p2, 12);
    const seed = hashCode(el.id);
    for (let pass = 0; pass < 2; pass++) {
      const rng = seededRandom(seed + pass * 1000);
      ctx.beginPath();
      for (let i = 1; i < pts.length; i++) roughLine(ctx, pts[i - 1].x, pts[i - 1].y, pts[i].x, pts[i].y, r, rng);
      ctx.stroke();
    }
  }

  function drawLine(ctx, el) {
    const r = el.roughness ?? 0;
    // Curved line (has control point)
    if (el.cp) {
      const { s, e } = lineStartEnd(el);
      strokeCurvedLine(ctx, el, s, e);
      return;
    }
    if (el.pts && el.pts.length > 1) {
      if (r === 0) {
        ctx.beginPath();
        ctx.moveTo(el.pts[0].x, el.pts[0].y);
        for (let i = 1; i < el.pts.length; i++) ctx.lineTo(el.pts[i].x, el.pts[i].y);
        ctx.stroke();
      } else {
        const seed = hashCode(el.id);
        for (let pass = 0; pass < 2; pass++) {
          const rng = seededRandom(seed + pass * 1000);
          ctx.beginPath();
          for (let i = 1; i < el.pts.length; i++) roughLine(ctx, el.pts[i-1].x, el.pts[i-1].y, el.pts[i].x, el.pts[i].y, r, rng);
          ctx.stroke();
        }
      }
      return;
    }
    if (r === 0) {
      ctx.beginPath();
      ctx.moveTo(el.x, el.y);
      ctx.lineTo(el.x2, el.y2);
      ctx.stroke();
    } else {
      const seed = hashCode(el.id);
      for (let pass = 0; pass < 2; pass++) {
        const rng = seededRandom(seed + pass * 1000);
        ctx.beginPath();
        roughLine(ctx, el.x, el.y, el.x2, el.y2, r, rng);
        ctx.stroke();
      }
    }
  }

  function drawArrow(ctx, el) {
    const r = el.roughness ?? 0;
    let endX, endY, prevX, prevY;

    // Curved arrow: quadratic bezier with tangent-based arrowhead.
    if (el.cp) {
      const { s, e } = lineStartEnd(el);
      strokeCurvedLine(ctx, el, s, e);
      endX = e.x; endY = e.y;
      // Tangent at t=1 points from cp → end.
      prevX = el.cp.x; prevY = el.cp.y;
      const adx = endX - prevX, ady = endY - prevY;
      const alen = Math.hypot(adx, ady);
      if (alen < 1) return;
      const ux = adx / alen, uy = ady / alen;
      const hw = 10, hl = 18;
      ctx.setLineDash([]);
      ctx.beginPath();
      ctx.moveTo(endX, endY);
      ctx.lineTo(endX - hl * ux + hw * uy, endY - hl * uy - hw * ux);
      ctx.lineTo(endX - hl * ux - hw * uy, endY - hl * uy + hw * ux);
      ctx.closePath();
      ctx.fillStyle = el.strokeColor || "#1e1e2e";
      ctx.fill();
      return;
    }

    if (el.pts && el.pts.length > 1) {
      // Multi-point arrow
      if (r === 0) {
        ctx.beginPath();
        ctx.moveTo(el.pts[0].x, el.pts[0].y);
        for (let i = 1; i < el.pts.length; i++) ctx.lineTo(el.pts[i].x, el.pts[i].y);
        ctx.stroke();
      } else {
        const seed = hashCode(el.id);
        for (let pass = 0; pass < 2; pass++) {
          const rng = seededRandom(seed + pass * 1000);
          ctx.beginPath();
          for (let i = 1; i < el.pts.length; i++) roughLine(ctx, el.pts[i-1].x, el.pts[i-1].y, el.pts[i].x, el.pts[i].y, r, rng);
          ctx.stroke();
        }
      }
      endX = el.pts[el.pts.length-1].x; endY = el.pts[el.pts.length-1].y;
      prevX = el.pts[el.pts.length-2].x; prevY = el.pts[el.pts.length-2].y;
    } else {
      const dx = el.x2 - el.x, dy = el.y2 - el.y;
      const len = Math.hypot(dx, dy);
      if (len < 1) return;
      if (r === 0) {
        ctx.beginPath();
        ctx.moveTo(el.x, el.y);
        ctx.lineTo(el.x2, el.y2);
        ctx.stroke();
      } else {
        const seed = hashCode(el.id);
        for (let pass = 0; pass < 2; pass++) {
          const rng = seededRandom(seed + pass * 1000);
          ctx.beginPath();
          roughLine(ctx, el.x, el.y, el.x2, el.y2, r, rng);
          ctx.stroke();
        }
      }
      endX = el.x2; endY = el.y2;
      prevX = el.x; prevY = el.y;
    }

    // Arrowhead (always clean)
    const adx = endX - prevX, ady = endY - prevY;
    const alen = Math.hypot(adx, ady);
    if (alen < 1) return;
    const ux = adx / alen, uy = ady / alen;
    const hw = 10, hl = 18;
    ctx.setLineDash([]); // arrowhead always solid
    ctx.beginPath();
    ctx.moveTo(endX, endY);
    ctx.lineTo(endX - hl * ux + hw * uy, endY - hl * uy - hw * ux);
    ctx.lineTo(endX - hl * ux - hw * uy, endY - hl * uy + hw * ux);
    ctx.closePath();
    ctx.fillStyle = el.strokeColor || "#1e1e2e";
    ctx.fill();
  }

  function drawPencil(ctx, el) {
    if (!el.pts || el.pts.length < 2) return;
    ctx.beginPath();
    ctx.moveTo(el.pts[0].x, el.pts[0].y);
    for (let i = 1; i < el.pts.length; i++) {
      const mp = { x: (el.pts[i - 1].x + el.pts[i].x) / 2, y: (el.pts[i - 1].y + el.pts[i].y) / 2 };
      ctx.quadraticCurveTo(el.pts[i - 1].x, el.pts[i - 1].y, mp.x, mp.y);
    }
    ctx.stroke();
  }

  function drawText(ctx, el) {
    const fs = el.fontSize || 16;
    ctx.font = `${fs}px ${fontCSS(el.fontFamily)}`;
    ctx.fillStyle = el.strokeColor || "#1e1e2e";
    ctx.textBaseline = "top";
    const align = el.textAlign || "left";
    ctx.textAlign = align;
    const lines = (el.text || "").split("\n");
    const w = el.w || 0;
    lines.forEach((line, i) => {
      let tx = el.x;
      if (align === "center") tx = el.x + w / 2;
      else if (align === "right") tx = el.x + w;
      ctx.fillText(line, tx, el.y + i * fs * 1.3);
    });
    ctx.textAlign = "start";
  }

  function drawImage(ctx, el) {
    const img = getImage(el.src);
    const w = el.w || 200, h = el.h || 150;
    if (img.complete && img.naturalWidth) {
      ctx.drawImage(img, el.x, el.y, w, h);
    } else {
      // Placeholder while loading
      ctx.save();
      ctx.setLineDash([6, 4]);
      ctx.strokeStyle = "#999";
      ctx.lineWidth = 1.5;
      ctx.strokeRect(el.x, el.y, w, h);
      ctx.setLineDash([]);
      ctx.fillStyle = "#ccc";
      ctx.font = "14px sans-serif";
      ctx.textBaseline = "middle";
      ctx.textAlign = "center";
      ctx.fillText("Loading\u2026", el.x + w / 2, el.y + h / 2);
      ctx.restore();
    }
  }

  const ROTATE_HANDLE_DIST = 25; // pixels from top of selection box

  function drawSelection(ctx, el) {
    const bb = getBBox(el);
    const pad = 6;
    const angle = el.angle || 0;
    const cx = bb.x + bb.w / 2, cy = bb.y + bb.h / 2;
    const isLine = el.type === "line" || el.type === "arrow";

    ctx.save();
    ctx.globalAlpha = 1;

    // Rotate selection around element center
    if (angle) {
      ctx.translate(cx, cy);
      ctx.rotate(angle);
      ctx.translate(-cx, -cy);
    }

    // Dashed selection rect
    ctx.strokeStyle = "#3b82f6";
    ctx.lineWidth = 1.5 / vp.scale;
    ctx.setLineDash([4 / vp.scale, 3 / vp.scale]);
    ctx.strokeRect(bb.x - pad, bb.y - pad, bb.w + pad * 2, bb.h + pad * 2);
    ctx.setLineDash([]);

    function drawHandle(hx, hy) {
      ctx.beginPath();
      ctx.arc(hx, hy, 4 / vp.scale, 0, Math.PI * 2);
      ctx.fillStyle = "#fff";
      ctx.fill();
      ctx.strokeStyle = "#3b82f6";
      ctx.lineWidth = 1.5 / vp.scale;
      ctx.stroke();
    }

    // Rotation handle — stem line from top-center to handle (all elements).
    {
      const handleDist = ROTATE_HANDLE_DIST / vp.scale;
      const stemX = bb.x + bb.w / 2;
      const stemTopY = bb.y - pad;
      const handleY = stemTopY - handleDist;

      ctx.beginPath();
      ctx.moveTo(stemX, stemTopY);
      ctx.lineTo(stemX, handleY);
      ctx.strokeStyle = "#3b82f6";
      ctx.lineWidth = 1 / vp.scale;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(stemX, handleY, 5 / vp.scale, 0, Math.PI * 2);
      ctx.fillStyle = "#fff";
      ctx.fill();
      ctx.strokeStyle = "#3b82f6";
      ctx.lineWidth = 1.5 / vp.scale;
      ctx.stroke();
    }

    if (isLine) {
      // Endpoint handles drawn in world coords (not rotated) to match existing hit-testing.
      ctx.restore(); // un-rotate for accurate world positions
      ctx.save();
      ctx.globalAlpha = 1;
      const ep = getLineEndpoints(el);
      drawHandle(ep.start.x, ep.start.y);
      drawHandle(ep.end.x, ep.end.y);
      // Mid handle — draggable control point for curving the line.
      const mh = lineMidHandlePos(el);
      ctx.beginPath();
      ctx.arc(mh.x, mh.y, 5 / vp.scale, 0, Math.PI * 2);
      ctx.fillStyle = el.cp ? "#c7d2fe" : "#e0e7ff";
      ctx.fill();
      ctx.strokeStyle = "#3b82f6";
      ctx.lineWidth = 1.5 / vp.scale;
      ctx.stroke();
    } else {
      // Corner resize handles for shapes
      const corners = [
        [bb.x - pad, bb.y - pad],
        [bb.x + bb.w + pad, bb.y - pad],
        [bb.x - pad, bb.y + bb.h + pad],
        [bb.x + bb.w + pad, bb.y + bb.h + pad],
      ];
      corners.forEach(([hx, hy]) => drawHandle(hx, hy));
    }

    ctx.restore();
  }

  // Compute the combined axis-aligned bounding box for a set of elements,
  // accounting for each element's own rotation.
  function getElementsBBox(elements) {
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const el of elements) {
      const bb = getBBox(el);
      const angle = el.angle || 0;
      if (!angle) {
        minX = Math.min(minX, bb.x); minY = Math.min(minY, bb.y);
        maxX = Math.max(maxX, bb.x + bb.w); maxY = Math.max(maxY, bb.y + bb.h);
      } else {
        const cx = bb.x + bb.w / 2, cy = bb.y + bb.h / 2;
        for (const [px, py] of [[bb.x,bb.y],[bb.x+bb.w,bb.y],[bb.x,bb.y+bb.h],[bb.x+bb.w,bb.y+bb.h]]) {
          const r = rotatePoint(px, py, cx, cy, angle);
          minX = Math.min(minX, r.x); minY = Math.min(minY, r.y);
          maxX = Math.max(maxX, r.x); maxY = Math.max(maxY, r.y);
        }
      }
    }
    return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
  }

  // Combined selection box + corner + rotation handles for a group.
  function drawGroupSelection(ctx, group) {
    const bb = getElementsBBox(group);
    const pad = 6;
    ctx.save();
    ctx.strokeStyle = "#3b82f6";
    ctx.lineWidth = 1.5 / vp.scale;
    ctx.setLineDash([4 / vp.scale, 3 / vp.scale]);
    ctx.strokeRect(bb.x - pad, bb.y - pad, bb.w + pad * 2, bb.h + pad * 2);
    ctx.setLineDash([]);
    // Corner handles
    for (const [hx, hy] of [
      [bb.x-pad, bb.y-pad], [bb.x+bb.w+pad, bb.y-pad],
      [bb.x-pad, bb.y+bb.h+pad], [bb.x+bb.w+pad, bb.y+bb.h+pad],
    ]) {
      ctx.beginPath();
      ctx.arc(hx, hy, 4 / vp.scale, 0, Math.PI * 2);
      ctx.fillStyle = "#fff"; ctx.fill();
      ctx.strokeStyle = "#3b82f6"; ctx.lineWidth = 1.5 / vp.scale; ctx.stroke();
    }
    // Rotation handle
    const handleDist = ROTATE_HANDLE_DIST / vp.scale;
    const stemX = bb.x + bb.w / 2;
    const stemTopY = bb.y - pad;
    const handleY = stemTopY - handleDist;
    ctx.beginPath();
    ctx.moveTo(stemX, stemTopY); ctx.lineTo(stemX, handleY);
    ctx.strokeStyle = "#3b82f6"; ctx.lineWidth = 1 / vp.scale; ctx.stroke();
    ctx.beginPath();
    ctx.arc(stemX, handleY, 5 / vp.scale, 0, Math.PI * 2);
    ctx.fillStyle = "#fff"; ctx.fill();
    ctx.strokeStyle = "#3b82f6"; ctx.lineWidth = 1.5 / vp.scale; ctx.stroke();
    ctx.restore();
  }

  // Return the group handle at (wx, wy) or null.
  // Handles: "nw","ne","sw","se","rotate".
  function hitTestGroupHandles(bb, wx, wy) {
    const pad = 6;
    const threshold = 10 / vp.scale;
    const handles = {
      nw: { x: bb.x - pad, y: bb.y - pad },
      ne: { x: bb.x + bb.w + pad, y: bb.y - pad },
      sw: { x: bb.x - pad, y: bb.y + bb.h + pad },
      se: { x: bb.x + bb.w + pad, y: bb.y + bb.h + pad },
      rotate: { x: bb.x + bb.w / 2, y: bb.y - pad - ROTATE_HANDLE_DIST / vp.scale },
    };
    for (const [k, p] of Object.entries(handles)) {
      if (Math.hypot(wx - p.x, wy - p.y) < threshold) return k;
    }
    return null;
  }

  // Apply a scale+translate to a single element. Scaling is relative to the
  // fixed corner (fx, fy) by factor s. Mutates the element in place.
  function scaleElement(el, fx, fy, sx, sy) {
    switch (el.type) {
      case "rect": case "diamond": case "ellipse": case "text": case "image": {
        el.x = fx + (el.x - fx) * sx;
        el.y = fy + (el.y - fy) * sy;
        el.w *= sx; el.h *= sy;
        break;
      }
      case "line": case "arrow": {
        if (el.pts) {
          el.pts = el.pts.map(p => ({ x: fx + (p.x - fx) * sx, y: fy + (p.y - fy) * sy }));
        } else {
          el.x = fx + (el.x - fx) * sx; el.y = fy + (el.y - fy) * sy;
          el.x2 = fx + (el.x2 - fx) * sx; el.y2 = fy + (el.y2 - fy) * sy;
        }
        if (el.cp) el.cp = { x: fx + (el.cp.x - fx) * sx, y: fy + (el.cp.y - fy) * sy };
        break;
      }
      case "pencil": {
        if (el.pts) {
          el.pts = el.pts.map(p => ({ x: fx + (p.x - fx) * sx, y: fy + (p.y - fy) * sy }));
        }
        break;
      }
    }
  }

  // Rotate a single element around (cx, cy) by delta radians.
  function rotateElementAround(el, cx, cy, delta) {
    const rotPt = (p) => rotatePoint(p.x, p.y, cx, cy, delta);
    switch (el.type) {
      case "rect": case "diamond": case "ellipse": case "text": case "image": {
        // Rotate element center around group center, keep size.
        const ec = { x: el.x + el.w / 2, y: el.y + el.h / 2 };
        const r = rotPt(ec);
        el.x = r.x - el.w / 2; el.y = r.y - el.h / 2;
        el.angle = (el.angle || 0) + delta;
        break;
      }
      case "line": case "arrow": {
        if (el.pts) {
          el.pts = el.pts.map(p => rotPt(p));
        } else {
          const s = rotPt({ x: el.x, y: el.y }); el.x = s.x; el.y = s.y;
          const e2 = rotPt({ x: el.x2, y: el.y2 }); el.x2 = e2.x; el.y2 = e2.y;
        }
        if (el.cp) el.cp = rotPt(el.cp);
        // Lines can have their own angle too; compose.
        if (el.angle) el.angle += delta;
        break;
      }
      case "pencil": {
        if (el.pts) el.pts = el.pts.map(p => rotPt(p));
        break;
      }
    }
  }

  function getRotationHandlePos(el) {
    const bb = getBBox(el);
    const pad = 6;
    const angle = el.angle || 0;
    const cx = bb.x + bb.w / 2, cy = bb.y + bb.h / 2;
    const handleDist = ROTATE_HANDLE_DIST / vp.scale;
    const localX = bb.x + bb.w / 2;
    const localY = bb.y - pad - handleDist;
    if (!angle) return { x: localX, y: localY };
    return rotatePoint(localX, localY, cx, cy, angle);
  }

  function getResizeHandles(el) {
    const bb = getBBox(el);
    const pad = 6;
    const angle = el.angle || 0;
    const cx = bb.x + bb.w / 2, cy = bb.y + bb.h / 2;
    const raw = {
      nw: { x: bb.x - pad, y: bb.y - pad },
      ne: { x: bb.x + bb.w + pad, y: bb.y - pad },
      sw: { x: bb.x - pad, y: bb.y + bb.h + pad },
      se: { x: bb.x + bb.w + pad, y: bb.y + bb.h + pad },
    };
    if (angle) {
      for (const k of Object.keys(raw)) raw[k] = rotatePoint(raw[k].x, raw[k].y, cx, cy, angle);
    }
    return raw;
  }

  function getLineEndpoints(el) {
    if (el.pts && el.pts.length > 1) {
      return { start: { x: el.pts[0].x, y: el.pts[0].y }, end: { x: el.pts[el.pts.length-1].x, y: el.pts[el.pts.length-1].y } };
    }
    return { start: { x: el.x, y: el.y }, end: { x: el.x2, y: el.y2 } };
  }

  const HANDLE_CURSORS = { nw: "nwse-resize", ne: "nesw-resize", sw: "nesw-resize", se: "nwse-resize", start: "crosshair", end: "crosshair", mid: "move" };

  function hitTestHandles(el, wx, wy) {
    const threshold = 8 / vp.scale;
    if (el.type === "line" || el.type === "arrow") {
      const ep = getLineEndpoints(el);
      if (Math.hypot(wx - ep.start.x, wy - ep.start.y) < threshold) return "start";
      if (Math.hypot(wx - ep.end.x, wy - ep.end.y) < threshold) return "end";
      const mh = lineMidHandlePos(el);
      if (Math.hypot(wx - mh.x, wy - mh.y) < threshold) return "mid";
      return null;
    }
    const handles = getResizeHandles(el);
    for (const [k, pos] of Object.entries(handles)) {
      if (Math.hypot(wx - pos.x, wy - pos.y) < threshold) return k;
    }
    return null;
  }

  function getBBox(el) {
    switch (el.type) {
      case "rect":
      case "diamond":
      case "ellipse":
      case "text":
      case "image":
        return { x: el.x, y: el.y, w: el.w || 0, h: el.h || 0 };
      case "line":
      case "arrow": {
        let xs, ys;
        if (el.pts && el.pts.length > 1) {
          xs = el.pts.map(p => p.x); ys = el.pts.map(p => p.y);
        } else {
          xs = [el.x, el.x2]; ys = [el.y, el.y2];
        }
        if (el.cp) { xs = xs.concat([el.cp.x]); ys = ys.concat([el.cp.y]); }
        const mx = Math.min(...xs), my = Math.min(...ys);
        return { x: mx, y: my, w: Math.max(...xs) - mx, h: Math.max(...ys) - my };
      }
      case "pencil": {
        if (!el.pts || !el.pts.length) return { x: 0, y: 0, w: 0, h: 0 };
        const xs = el.pts.map(p => p.x), ys = el.pts.map(p => p.y);
        const x = Math.min(...xs), y = Math.min(...ys);
        return { x, y, w: Math.max(...xs) - x, h: Math.max(...ys) - y };
      }
      default:
        return { x: 0, y: 0, w: 0, h: 0 };
    }
  }

  function getCenter(el) {
    const bb = getBBox(el);
    return { x: bb.x + bb.w / 2, y: bb.y + bb.h / 2 };
  }

  function rotatePoint(px, py, cx, cy, angle) {
    const cos = Math.cos(angle), sin = Math.sin(angle);
    const dx = px - cx, dy = py - cy;
    return { x: cx + dx * cos - dy * sin, y: cy + dx * sin + dy * cos };
  }

  // ── Hit testing ───────────────────────────────────────────────────────────
  function hitTest(el, wx, wy) {
    // Un-rotate the test point into element's local coordinate space
    const angle = el.angle || 0;
    if (angle) {
      const c = getCenter(el);
      const p = rotatePoint(wx, wy, c.x, c.y, -angle);
      wx = p.x;
      wy = p.y;
    }
    const pad = 8;
    switch (el.type) {
      case "rect":
      case "diamond":
      case "ellipse":
      case "text":
      case "image": {
        const x0 = Math.min(el.x, el.x + el.w), y0 = Math.min(el.y, el.y + el.h);
        const x1 = x0 + Math.abs(el.w), y1 = y0 + Math.abs(el.h);
        return wx >= x0 - pad && wx <= x1 + pad && wy >= y0 - pad && wy <= y1 + pad;
      }
      case "line":
      case "arrow": {
        if (el.cp) {
          const { s, e } = lineStartEnd(el);
          const samples = sampleBezier(s, el.cp, e, 16);
          for (let i = 1; i < samples.length; i++) {
            if (distToSegment(wx, wy, samples[i-1].x, samples[i-1].y, samples[i].x, samples[i].y) < pad + el.strokeWidth) return true;
          }
          return false;
        }
        if (el.pts && el.pts.length > 1) {
          for (let i = 1; i < el.pts.length; i++) {
            if (distToSegment(wx, wy, el.pts[i-1].x, el.pts[i-1].y, el.pts[i].x, el.pts[i].y) < pad + el.strokeWidth) return true;
          }
          return false;
        }
        return distToSegment(wx, wy, el.x, el.y, el.x2, el.y2) < pad + el.strokeWidth;
      }
      case "pencil": {
        if (!el.pts) return false;
        for (let i = 1; i < el.pts.length; i++) {
          if (distToSegment(wx, wy, el.pts[i-1].x, el.pts[i-1].y, el.pts[i].x, el.pts[i].y) < pad + el.strokeWidth) return true;
        }
        return false;
      }
      default: return false;
    }
  }

  function distToSegment(px, py, ax, ay, bx, by) {
    const dx = bx - ax, dy = by - ay;
    const lenSq = dx * dx + dy * dy;
    if (lenSq === 0) return Math.hypot(px - ax, py - ay);
    let t = ((px - ax) * dx + (py - ay) * dy) / lenSq;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(px - (ax + t * dx), py - (ay + t * dy));
  }

  // ── Events ────────────────────────────────────────────────────────────────
  // All pointer input (mouse, pen, touch) flows through a single pointer-
  // event pipeline à la Excalidraw. We still keep the mouse handlers around
  // for the existing code path — the pointer handlers call them directly.
  // Separate wheel/dblclick listeners remain for mouse-specific gestures.
  // The legacy touch listeners only run if PointerEvent is unavailable.
  function attachCanvasEvents() {
    canvas.addEventListener("wheel", onWheel, { passive: false });
    canvas.addEventListener("dblclick", onDblClick);

    if (typeof window.PointerEvent === "function") {
      canvas.addEventListener("pointerdown", onPointerDown);
      canvas.addEventListener("pointermove", onPointerMove);
      canvas.addEventListener("pointerup", onPointerUp);
      canvas.addEventListener("pointercancel", onPointerUp);
    } else {
      // Legacy fallback for browsers without PointerEvent.
      canvas.addEventListener("mousedown", onMouseDown);
      canvas.addEventListener("mousemove", onMouseMove);
      canvas.addEventListener("mouseup", onMouseUp);
      canvas.addEventListener("mouseleave", onMouseUp);
      canvas.addEventListener("touchstart", onTouchStart, { passive: false });
      canvas.addEventListener("touchmove", onTouchMove, { passive: false });
      canvas.addEventListener("touchend", onTouchEnd);
    }
  }

  // Active pointers are tracked so we can detect single- vs multi-pointer
  // gestures. `primaryPointerId` is the id the tool is currently following.
  const activePointers = new Map(); // pointerId → { x, y, type }
  let primaryPointerId = null;
  let twoPointerGesture = null;     // { cx, cy, dist }

  function synthMouseEvent(pe) {
    return {
      button: pe.button != null ? pe.button : 0,
      clientX: pe.clientX,
      clientY: pe.clientY,
      shiftKey: !!pe.shiftKey,
      ctrlKey: !!pe.ctrlKey,
      metaKey: !!pe.metaKey,
      altKey: !!pe.altKey,
      preventDefault: () => { if (pe.preventDefault) pe.preventDefault(); },
      stopPropagation: () => { if (pe.stopPropagation) pe.stopPropagation(); },
    };
  }

  function onPointerDown(e) {
    // Let non-primary mouse buttons (e.g. right-click) fall through.
    if (e.pointerType === "mouse" && e.button !== 0 && e.button !== 1) return;
    e.preventDefault();
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY, type: e.pointerType });

    if (activePointers.size === 1) {
      primaryPointerId = e.pointerId;
      try { canvas.setPointerCapture(e.pointerId); } catch (_) {}
      onMouseDown(synthMouseEvent(e));
      return;
    }

    if (activePointers.size === 2) {
      // Cancel any in-progress single-pointer action so the second pointer
      // can initiate pan/pinch cleanly.
      if (primaryPointerId != null) {
        onMouseUp(synthMouseEvent(e));
        primaryPointerId = null;
      }
      const pts = [...activePointers.values()];
      twoPointerGesture = {
        cx: (pts[0].x + pts[1].x) / 2,
        cy: (pts[0].y + pts[1].y) / 2,
        dist: Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y),
      };
    }
  }

  function onPointerMove(e) {
    if (!activePointers.has(e.pointerId)) return;
    activePointers.set(e.pointerId, { x: e.clientX, y: e.clientY, type: e.pointerType });
    e.preventDefault();

    if (activePointers.size === 1 && e.pointerId === primaryPointerId) {
      onMouseMove(synthMouseEvent(e));
      return;
    }

    if (activePointers.size >= 2 && twoPointerGesture) {
      const pts = [...activePointers.values()];
      const cx = (pts[0].x + pts[1].x) / 2;
      const cy = (pts[0].y + pts[1].y) / 2;
      const dist = Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y);
      // Pan by centroid delta.
      vp.x += cx - twoPointerGesture.cx;
      vp.y += cy - twoPointerGesture.cy;
      // Pinch-zoom around centroid.
      if (twoPointerGesture.dist > 0) {
        const factor = dist / twoPointerGesture.dist;
        const rect = canvas.getBoundingClientRect();
        const px = cx - rect.left, py = cy - rect.top;
        const newScale = Math.max(0.1, Math.min(10, vp.scale * factor));
        vp.x = px - (px - vp.x) * (newScale / vp.scale);
        vp.y = py - (py - vp.y) * (newScale / vp.scale);
        vp.scale = newScale;
      }
      twoPointerGesture = { cx, cy, dist };
      render();
    }
  }

  function onPointerUp(e) {
    if (!activePointers.has(e.pointerId)) return;
    activePointers.delete(e.pointerId);
    try { canvas.releasePointerCapture(e.pointerId); } catch (_) {}

    if (e.pointerId === primaryPointerId) {
      onMouseUp(synthMouseEvent(e));
      primaryPointerId = null;
    }
    if (activePointers.size < 2) {
      twoPointerGesture = null;
    }
  }

  function onMouseDown(e) {
    if (e.button === 1 || (e.button === 0 && (e.altKey || e.spaceKey))) {
      // Middle click = pan
      startPan(e);
      return;
    }
    if (e.button !== 0) return;
    const { cx, cy } = getMousePos(e);

    // Spacebar held = pan regardless of tool
    if (spaceDown) { startPan(e); return; }

    const { x: wx, y: wy } = canvasToWorld(cx, cy);
    startX = wx; startY = wy;

    if (!IS_EDIT) {
      startPan(e);
      return;
    }

    if (activeTool === "hand") {
      startPan(e);
      return;
    }

    if (activeTool === "select") {
      // Check group handles first when a group of elements is selected.
      if (selectedIds.size > 1) {
        const selArr = scene.elements.filter(el => selectedIds.has(el.id));
        const groupBB = getElementsBBox(selArr);
        const gh = hitTestGroupHandles(groupBB, wx, wy);
        if (gh) {
          const originals = new Map();
          for (const el of selArr) originals.set(el.id, JSON.parse(JSON.stringify(el)));
          groupTransform = {
            mode: gh === "rotate" ? "rotate" : "resize",
            handle: gh,
            bbox: groupBB,
            center: { x: groupBB.x + groupBB.w / 2, y: groupBB.y + groupBB.h / 2 },
            originals,
            rotateStartAngle: Math.atan2(wy - (groupBB.y + groupBB.h / 2), wx - (groupBB.x + groupBB.w / 2)),
          };
          snapshot();
          canvas.style.cursor = gh === "rotate" ? "grabbing" : (HANDLE_CURSORS[gh] || "default");
          return;
        }
      }
      // Check rotation handle first (only when exactly one element selected)
      if (selectedIds.size === 1) {
        const sel = scene.elements.find(e => selectedIds.has(e.id));
        if (sel) {
          const rh = getRotationHandlePos(sel);
          if (Math.hypot(wx - rh.x, wy - rh.y) < 8 / vp.scale) {
            isRotating = true;
            const c = getCenter(sel);
            rotateStartAngle = Math.atan2(wy - c.y, wx - c.x);
            rotateOriginalAngle = sel.angle || 0;
            snapshot();
            canvas.style.cursor = "grabbing";
            render();
            return;
          }
          // Check resize handles
          const rHandle = hitTestHandles(sel, wx, wy);
          if (rHandle) {
            isResizing = true;
            resizeHandle = rHandle;
            resizeOriginal = JSON.parse(JSON.stringify(sel));
            snapshot();
            canvas.style.cursor = HANDLE_CURSORS[rHandle] || "default";
            return;
          }
        }
      }
      // Hit test in reverse (topmost first)
      const hit = [...scene.elements].reverse().find(el => hitTest(el, wx, wy));
      if (hit) {
        // If the element is part of a group, expand the hit to the whole group
        // so clicking any piece selects the whole library item.
        const hitIds = hit.groupId
          ? scene.elements.filter(el => el.groupId === hit.groupId).map(el => el.id)
          : [hit.id];
        if (e.shiftKey) {
          // Shift+click: toggle group in/out of selection
          selectedIds = new Set(selectedIds);
          const allIn = hitIds.every(id => selectedIds.has(id));
          if (allIn) hitIds.forEach(id => selectedIds.delete(id));
          else hitIds.forEach(id => selectedIds.add(id));
        } else if (!selectedIds.has(hit.id)) {
          selectedIds = new Set(hitIds);
        }
        isDragging = true;
        dragOffset = { x: wx - startX, y: wy - startY };
      } else {
        if (!e.shiftKey) selectedIds.clear();
        // Start marquee selection on empty area
        marquee = { x: wx, y: wy, w: 0, h: 0 };
      }
      render();
      return;
    }

    if (activeTool === "eraser") {
      snapshot();
      eraserActive = true;
      erasedIds = new Set();
      // Erase anything under the cursor
      const hit = scene.elements.find(el => hitTest(el, wx, wy));
      if (hit) {
        erasedIds.add(hit.id);
        scene.elements = scene.elements.filter(el => el.id !== hit.id);
      }
      render();
      return;
    }

    if (activeTool === "image") {
      const clickX = wx, clickY = wy;
      const input = document.createElement("input");
      input.type = "file";
      input.accept = "image/*";
      input.onchange = async () => {
        if (!input.files || !input.files[0]) return;
        const fd = new FormData();
        fd.append("file", input.files[0]);
        try {
          const res = await fetch(`${CFG.basePath}/api/upload`, { method: "POST", body: fd });
          if (!res.ok) throw new Error(await res.text());
          const data = await res.json();
          snapshot();
          const img = getImage(data.url);
          const imgEl = {
            id: uid(), type: "image",
            x: clickX, y: clickY,
            w: 200, h: 150,
            src: data.url,
            opacity: 100,
          };
          // Try to use natural dimensions once loaded
          if (img.complete && img.naturalWidth) {
            imgEl.w = Math.min(img.naturalWidth, 400);
            imgEl.h = imgEl.w * (img.naturalHeight / img.naturalWidth);
          }
          scene.elements.push(imgEl);
          setTool("select");
          selectedIds = new Set([imgEl.id]);
          render();
        } catch (err) {
          console.error("go-draw: upload failed", err);
        }
      };
      input.click();
      return;
    }

    if (activeTool === "text") {
      e.preventDefault(); // prevent browser focus logic from stealing textarea focus
      commitTextInput();
      // If clicking on an existing element, edit its text
      const hit = [...scene.elements].reverse().find(el => hitTest(el, wx, wy));
      if (hit && hit.type === "text") {
        startTextInputOnElement(hit);
      } else if (hit && (hit.type === "rect" || hit.type === "diamond" || hit.type === "ellipse")) {
        startTextInputOnShape(hit);
      } else {
        startTextInput(wx, wy);
      }
      return;
    }

    // Start new shape
    drawing = true;
    pencilPoints = [{ x: wx, y: wy }];
    currentEl = makeElement(wx, wy);
  }

  function onMouseMove(e) {
    if (panning) {
      const { cx, cy } = getMousePos(e);
      vp.x = panStart.vpx + (cx - panStart.x);
      vp.y = panStart.vpy + (cy - panStart.y);
      render();
      return;
    }
    if (!IS_EDIT) return;

    const { cx, cy } = getMousePos(e);
    const { x: wx, y: wy } = canvasToWorld(cx, cy);

    // Broadcast cursor position to collab peers
    if (CFG.collabEnabled && window.GodrawCollab) {
      window.GodrawCollab.sendCursorPosition(wx, wy);
    }

    // Track eraser cursor position for visual feedback
    if (activeTool === "eraser") {
      eraserCursorPos = { cx, cy };
      if (eraserActive) {
        const hit = scene.elements.find(el => hitTest(el, wx, wy));
        if (hit && !erasedIds.has(hit.id)) {
          erasedIds.add(hit.id);
          scene.elements = scene.elements.filter(el => el.id !== hit.id);
        }
      }
      render();
      return;
    }

    // Resize / rotation handle cursor feedback
    if (activeTool === "select" && selectedIds.size === 1 && !isDragging && !isRotating && !isResizing) {
      const sel = scene.elements.find(e => selectedIds.has(e.id));
      if (sel) {
        const rh = getRotationHandlePos(sel);
        if (Math.hypot(wx - rh.x, wy - rh.y) < 8 / vp.scale) {
          canvas.style.cursor = "grab";
        } else {
          const rHandle = hitTestHandles(sel, wx, wy);
          if (rHandle) {
            canvas.style.cursor = HANDLE_CURSORS[rHandle] || "default";
          } else {
            canvas.style.cursor = hitTest(sel, wx, wy) ? "move" : "default";
          }
        }
      }
    }

    // Group transform (resize or rotate a whole group)
    if (groupTransform) {
      const gt = groupTransform;
      if (gt.mode === "rotate") {
        const ang = Math.atan2(wy - gt.center.y, wx - gt.center.x);
        let delta = ang - gt.rotateStartAngle;
        if (e.shiftKey) delta = Math.round(delta / (Math.PI / 12)) * (Math.PI / 12);
        for (const el of scene.elements) {
          if (!gt.originals.has(el.id)) continue;
          const orig = gt.originals.get(el.id);
          // Reset element to original, then rotate fresh.
          Object.assign(el, JSON.parse(JSON.stringify(orig)));
          rotateElementAround(el, gt.center.x, gt.center.y, delta);
        }
      } else {
        // Resize: fixed point is the opposite corner of the dragged handle.
        const bb = gt.bbox;
        const fx = (gt.handle === "nw" || gt.handle === "sw") ? bb.x + bb.w : bb.x;
        const fy = (gt.handle === "nw" || gt.handle === "ne") ? bb.y + bb.h : bb.y;
        const newW = Math.max(4, Math.abs(wx - fx));
        const newH = Math.max(4, Math.abs(wy - fy));
        // Uniform scale by default (preserves aspect); Shift allows non-uniform.
        let sx = newW / bb.w, sy = newH / bb.h;
        if (!e.shiftKey) {
          const u = Math.hypot(newW, newH) / Math.hypot(bb.w, bb.h);
          sx = u; sy = u;
        }
        // Prevent negative (flipping) for simplicity.
        sx = Math.max(0.05, sx); sy = Math.max(0.05, sy);
        for (const el of scene.elements) {
          if (!gt.originals.has(el.id)) continue;
          const orig = gt.originals.get(el.id);
          Object.assign(el, JSON.parse(JSON.stringify(orig)));
          scaleElement(el, fx, fy, sx, sy);
        }
      }
      render();
      return;
    }

    // Rotation dragging
    if (isRotating && selectedIds.size === 1) {
      const sel = scene.elements.find(e => selectedIds.has(e.id));
      if (sel) {
        const c = getCenter(sel);
        const currentAngle = Math.atan2(wy - c.y, wx - c.x);
        let newAngle = rotateOriginalAngle + (currentAngle - rotateStartAngle);
        // Snap to 15° when Shift held
        if (e.shiftKey) {
          newAngle = Math.round(newAngle / (Math.PI / 12)) * (Math.PI / 12);
        }
        sel.angle = newAngle;
      }
      render();
      return;
    }

    // Resize dragging
    if (isResizing && selectedIds.size === 1 && resizeOriginal) {
      const sel = scene.elements.find(e => selectedIds.has(e.id));
      if (sel) {
        const o = resizeOriginal;
        const angle = o.angle || 0;
        // Un-rotate mouse into element's local frame
        let lx = wx, ly = wy;
        if (angle) {
          const c = { x: o.x + (o.w || 0) / 2, y: o.y + (o.h || 0) / 2 };
          const p = rotatePoint(wx, wy, c.x, c.y, -angle);
          lx = p.x; ly = p.y;
        }

        if (sel.type === "line" || sel.type === "arrow") {
          // Line/arrow endpoint dragging
          if (resizeHandle === "start") {
            if (sel.pts && sel.pts.length > 1) { sel.pts[0] = { x: wx, y: wy }; }
            else { sel.x = wx; sel.y = wy; }
          } else if (resizeHandle === "end") {
            if (sel.pts && sel.pts.length > 1) { sel.pts[sel.pts.length - 1] = { x: wx, y: wy }; }
            else { sel.x2 = wx; sel.y2 = wy; }
          } else if (resizeHandle === "mid") {
            // Drag midpoint to curve the line. Snap back to straight if dragged
            // onto the chord.
            const { s, e: ee } = lineStartEnd(sel);
            const mx = (s.x + ee.x) / 2, my = (s.y + ee.y) / 2;
            const snap = 3 / vp.scale;
            if (Math.hypot(wx - mx, wy - my) < snap) {
              delete sel.cp;
            } else {
              sel.cp = { x: wx, y: wy };
            }
          }
        } else {
          // Shape corner resize
          const fixedX = (resizeHandle === "nw" || resizeHandle === "sw") ? o.x + o.w : o.x;
          const fixedY = (resizeHandle === "nw" || resizeHandle === "ne") ? o.y + o.h : o.y;
          let newX = Math.min(fixedX, lx), newY = Math.min(fixedY, ly);
          let newW = Math.abs(lx - fixedX), newH = Math.abs(ly - fixedY);
          // Shift = maintain aspect ratio
          if (e.shiftKey && o.w && o.h) {
            const aspect = Math.abs(o.w / o.h);
            if (newW / newH > aspect) newW = newH * aspect;
            else newH = newW / aspect;
            if (resizeHandle === "nw") { newX = fixedX - newW; newY = fixedY - newH; }
            else if (resizeHandle === "ne") { newY = fixedY - newH; }
            else if (resizeHandle === "sw") { newX = fixedX - newW; }
          }
          sel.x = newX; sel.y = newY; sel.w = newW; sel.h = newH;
        }
      }
      render();
      return;
    }

    if (isDragging && selectedIds.size) {
      const dx = wx - startX, dy = wy - startY;
      for (const el of scene.elements) {
        if (!selectedIds.has(el.id)) continue;
        moveElement(el, dx, dy);
      }
      startX = wx; startY = wy;
      render();
      return;
    }

    // Marquee drag update
    if (marquee) {
      marquee.w = wx - marquee.x;
      marquee.h = wy - marquee.y;
      render();
      return;
    }

    if (!drawing) return;
    updateElement(currentEl, wx, wy);
    if (activeTool === "pencil") {
      pencilPoints.push({ x: wx, y: wy });
      currentEl.pts = [...pencilPoints];
    }
    render();
  }

  function onMouseUp(e) {
    if (panning) {
      panning = false;
      if (activeTool === "hand") canvas.style.cursor = "grab";
      else if (activeTool === "eraser") canvas.style.cursor = "none";
      else if (activeTool === "select") canvas.style.cursor = "default";
      else canvas.style.cursor = IS_EDIT ? "crosshair" : "grab";
      return;
    }
    if (eraserActive) { eraserActive = false; erasedIds = new Set(); return; }
    if (groupTransform) { groupTransform = null; canvas.style.cursor = "default"; return; }
    if (isRotating) { isRotating = false; canvas.style.cursor = "default"; return; }
    if (isResizing) { isResizing = false; resizeHandle = ""; resizeOriginal = null; canvas.style.cursor = "default"; return; }
    if (isDragging) { isDragging = false; snapshot(); return; }
    if (marquee) {
      // Select all elements intersecting the marquee rectangle
      const mx = Math.min(marquee.x, marquee.x + marquee.w);
      const my = Math.min(marquee.y, marquee.y + marquee.h);
      const mw = Math.abs(marquee.w);
      const mh = Math.abs(marquee.h);
      if (mw > 2 || mh > 2) {
        for (const el of scene.elements) {
          const bb = getBBox(el);
          // Element intersects marquee if bounding boxes overlap
          if (bb.x + bb.w >= mx && bb.x <= mx + mw && bb.y + bb.h >= my && bb.y <= my + mh) {
            selectedIds.add(el.id);
          }
        }
      }
      marquee = null;
      render();
      return;
    }
    if (!drawing) return;
    drawing = false;
    if (currentEl) {
      const bb = getBBox(currentEl);
      const tooSmall = bb.w < 3 && bb.h < 3 && currentEl.type !== "pencil" && currentEl.type !== "image";
      if (!tooSmall) {
        snapshot();
        scene.elements.push(currentEl);
        const newId = currentEl.id;
        // Auto-switch back to select tool after drawing a shape (Excalidraw-style).
        // Pencil stays in pencil so the user can keep free-drawing.
        if (activeTool !== "pencil" && activeTool !== "eraser" && activeTool !== "text") {
          setTool("select");
        }
        selectedIds = new Set([newId]);
      }
      currentEl = null;
    }
    render();
  }

  let spaceDown = false;
  function onKeyDown(e) {
    if (e.code === "Space" && !e.repeat) {
      spaceDown = true;
      canvas.style.cursor = "grab";
    }
    if (e.target && (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA" || e.target.tagName === "SELECT")) return;
    const mod = e.ctrlKey || e.metaKey;
    if (mod && e.key === "z") { e.preventDefault(); undo(); }
    if (mod && (e.key === "y" || (e.shiftKey && e.key === "z"))) { e.preventDefault(); redo(); }
    if (mod && e.key === "s") { e.preventDefault(); saveDrawing(); }
    if (mod && (e.key === "d" || e.key === "D")) { e.preventDefault(); duplicateSelected(); }
    if (mod && e.key === "c") { e.preventDefault(); copySelected(); }
    if (mod && e.key === "v") { e.preventDefault(); pasteClipboard(); }
    if (mod && e.key === "x") { e.preventDefault(); cutSelected(); }
    if (mod && e.key === "a") { e.preventDefault(); selectAll(); }
    if (mod && e.shiftKey && (e.key === "g" || e.key === "G")) { e.preventDefault(); ungroupSelected(); }
    else if (mod && (e.key === "g" || e.key === "G")) { e.preventDefault(); groupSelected(); }
    if (e.key === "Delete" || e.key === "Backspace") deleteSelected();
    if (e.key === "h" || e.key === "H") setTool("hand");
    if (e.key === "v" || e.key === "V" || e.key === "1") setTool("select");
    if (e.key === "r" || e.key === "R" || e.key === "2") setTool("rect");
    if (e.key === "d" || e.key === "D") setTool("diamond");
    if (e.key === "e" || e.key === "E" || e.key === "3") setTool("ellipse");
    if (e.key === "l" || e.key === "L" || e.key === "4") setTool("line");
    if (e.key === "a" || e.key === "A" || e.key === "5") setTool("arrow");
    if (e.key === "p" || e.key === "P" || e.key === "6") setTool("pencil");
    if (e.key === "t" || e.key === "T" || e.key === "7") setTool("text");
    if (e.key === "x" || e.key === "X" || e.key === "8") setTool("eraser");
    if (e.key === "i" || e.key === "I" || e.key === "9") setTool("image");
    if (e.key === "0") setTool("select"); // 0 = quick back to select
    if (e.key === "Escape") { commitTextInput(); selectedIds.clear(); render(); }
    if (e.key === "F11") { e.preventDefault(); toggleFullscreen(); }
    if (e.key === "[") { e.preventDefault(); toggleSidebar(); }
    if (e.altKey && (e.key === "z" || e.key === "Z")) { e.preventDefault(); toggleZenMode(); }
  }

  window.addEventListener("keyup", e => {
    if (e.code === "Space") {
      spaceDown = false;
      if (activeTool === "hand") canvas.style.cursor = "grab";
      else if (activeTool === "eraser") canvas.style.cursor = "none";
      else if (activeTool === "select") canvas.style.cursor = "default";
      else canvas.style.cursor = IS_EDIT ? "crosshair" : "grab";
    }
  });

  function onViewKeyDown(e) {
    if (e.code === "Space" && !e.repeat) { spaceDown = true; canvas.style.cursor = "grab"; }
    if (e.key === "F11") { e.preventDefault(); toggleFullscreen(); }
  }

  function onDblClick(e) {
    if (!IS_EDIT) return;
    e.preventDefault();
    const { cx, cy } = getMousePos(e);
    const { x: wx, y: wy } = canvasToWorld(cx, cy);
    const hit = [...scene.elements].reverse().find(el => hitTest(el, wx, wy));
    if (hit && hit.groupId) {
      // Double-click on grouped element → select just this element (enter group).
      selectedIds = new Set([hit.id]);
      render();
      // If it's also a text or shape, continue into text editing.
      if (hit.type === "text") {
        commitTextInput();
        startTextInputOnElement(hit);
      } else if (hit.type === "rect" || hit.type === "diamond" || hit.type === "ellipse") {
        commitTextInput();
        startTextInputOnShape(hit);
      }
    } else if (hit && hit.type === "text") {
      selectedIds = new Set([hit.id]);
      commitTextInput();
      startTextInputOnElement(hit);
    } else if (hit && (hit.type === "rect" || hit.type === "diamond" || hit.type === "ellipse")) {
      // Double-click on shape → edit label text inside
      selectedIds = new Set([hit.id]);
      commitTextInput();
      startTextInputOnShape(hit);
    } else if (!hit) {
      // Double-click on empty canvas creates text
      setTool("text");
      commitTextInput();
      startTextInput(wx, wy);
    }
  }

  function onWheel(e) {
    e.preventDefault();
    const { cx, cy } = getMousePos(e);
    const zoomFactor = e.deltaY < 0 ? 1.08 : 0.93;
    const newScale = Math.max(0.1, Math.min(10, vp.scale * zoomFactor));
    vp.x = cx - (cx - vp.x) * (newScale / vp.scale);
    vp.y = cy - (cy - vp.y) * (newScale / vp.scale);
    vp.scale = newScale;
    render();
  }

  // Touch (single finger = pan, pinch = zoom)
  let lastTouchDist = 0;
  let lastTouches = null;
  function isStylusTouch(e) {
    // WebKit/iOS exposes Touch.touchType="stylus" for Apple Pencil.
    return e.touches && e.touches[0] && e.touches[0].touchType === "stylus";
  }
  // Excalidraw-style touch input:
  //   • 1 finger → routes through the mouse handler so the active tool
  //                (draw/select/erase/text) works identically to desktop.
  //                Exception: the hand tool still pans.
  //   • 2 fingers → pan + pinch-zoom, and cancels any in-progress single-
  //                 finger draw.
  //   • Apple Pencil / stylus → handled by the pointer-event path above,
  //                             skipped here to avoid double-firing.
  let touchDrawing = false;
  let twoFingerActive = false;
  let twoFingerLast = null;   // { cx, cy, dist }

  function synthFromTouch(touch, e) {
    return {
      button: 0,
      clientX: touch.clientX,
      clientY: touch.clientY,
      shiftKey: e.shiftKey || false,
      ctrlKey: e.ctrlKey || false,
      metaKey: e.metaKey || false,
      altKey: e.altKey || false,
      preventDefault: () => e.preventDefault(),
      stopPropagation: () => e.stopPropagation(),
    };
  }

  function onTouchStart(e) {
    if (isStylusTouch(e)) return;
    e.preventDefault();

    if (e.touches.length === 1) {
      // Hand tool always pans; everything else uses the mouse handler so
      // the finger can draw, select, move, etc.
      if (activeTool === "hand") {
        panning = true;
        panStart = { x: e.touches[0].clientX, y: e.touches[0].clientY, vpx: vp.x, vpy: vp.y };
        return;
      }
      touchDrawing = true;
      twoFingerActive = false;
      onMouseDown(synthFromTouch(e.touches[0], e));
      return;
    }

    if (e.touches.length >= 2) {
      // If we started a single-finger draw, cancel it so the second finger
      // can initiate pan/zoom cleanly.
      if (touchDrawing) {
        onMouseUp(synthFromTouch(e.touches[0], e));
        touchDrawing = false;
      }
      twoFingerActive = true;
      const [a, b] = [e.touches[0], e.touches[1]];
      twoFingerLast = {
        cx: (a.clientX + b.clientX) / 2,
        cy: (a.clientY + b.clientY) / 2,
        dist: Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY),
      };
    }
  }

  function onTouchMove(e) {
    if (isStylusTouch(e)) return;
    e.preventDefault();

    // Hand-tool single-finger pan.
    if (!touchDrawing && !twoFingerActive && panning && e.touches.length === 1) {
      vp.x = panStart.vpx + (e.touches[0].clientX - panStart.x);
      vp.y = panStart.vpy + (e.touches[0].clientY - panStart.y);
      render();
      return;
    }

    // Single-finger drawing/selecting/etc.
    if (touchDrawing && e.touches.length === 1) {
      onMouseMove(synthFromTouch(e.touches[0], e));
      return;
    }

    // Two-finger pan + pinch-zoom.
    if (twoFingerActive && e.touches.length >= 2 && twoFingerLast) {
      const [a, b] = [e.touches[0], e.touches[1]];
      const cx = (a.clientX + b.clientX) / 2;
      const cy = (a.clientY + b.clientY) / 2;
      const dist = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
      // Pan by centroid delta.
      vp.x += cx - twoFingerLast.cx;
      vp.y += cy - twoFingerLast.cy;
      // Pinch-zoom around centroid.
      if (twoFingerLast.dist > 0) {
        const factor = dist / twoFingerLast.dist;
        const rect = canvas.getBoundingClientRect();
        const px = cx - rect.left, py = cy - rect.top;
        const newScale = Math.max(0.1, Math.min(10, vp.scale * factor));
        vp.x = px - (px - vp.x) * (newScale / vp.scale);
        vp.y = py - (py - vp.y) * (newScale / vp.scale);
        vp.scale = newScale;
      }
      twoFingerLast = { cx, cy, dist };
      render();
    }
  }

  function onTouchEnd(e) {
    if (isStylusTouch(e)) return;
    // Finish any single-finger drawing on last-finger-up.
    if (touchDrawing && e.touches.length === 0) {
      // Use changedTouches to get the released touch's position.
      const t = e.changedTouches && e.changedTouches[0];
      if (t) onMouseUp(synthFromTouch(t, e));
      else onMouseUp({ button: 0, clientX: 0, clientY: 0, shiftKey: false, preventDefault: () => {}, stopPropagation: () => {} });
      touchDrawing = false;
    }
    if (twoFingerActive && e.touches.length < 2) {
      twoFingerActive = false;
      twoFingerLast = null;
    }
    if (e.touches.length === 0) {
      panning = false;
    }
  }

  // ── Pan helpers ───────────────────────────────────────────────────────────
  function startPan(e) {
    panning = true;
    const { cx, cy } = getMousePos(e);
    panStart = { x: cx, y: cy, vpx: vp.x, vpy: vp.y };
    canvas.style.cursor = "grabbing";
  }

  // ── Tool helpers ──────────────────────────────────────────────────────────
  function setTool(t) {
    activeTool = t;
    toolbar.querySelectorAll(".tool-btn").forEach(b => {
      b.classList.toggle("active", b.dataset.tool === t);
    });
    commitTextInput();
    selectedIds.clear();
    if (t === "eraser") {
      canvas.style.cursor = "none";
      eraserCursorPos = null;
    } else if (t === "select") {
      canvas.style.cursor = "default";
    } else if (t === "hand") {
      canvas.style.cursor = "grab";
    } else {
      canvas.style.cursor = "crosshair";
    }
    render();
  }

  // ── Property sync ─────────────────────────────────────────────────────────
  function setProp(name, value) {
    // Always update the global default
    switch (name) {
      case "strokeColor": strokeColor = value; break;
      case "fillColor": fillColor = value; break;
      case "strokeWidth": strokeWidth = value; break;
      case "strokeStyle": strokeStyle = value; break;
      case "fillStyle": fillStyle = value; break;
      case "roughness": roughness = value; break;
      case "roundness": roundness = value; break;
      case "opacity": opacity = value; break;
      case "fontSize": fontSize = value; break;
      case "fontFamily": fontFamily = value; break;
      case "textAlign": textAlign = value; break;
    }
    // Apply to selected elements
    if (selectedIds.size) {
      snapshot();
      for (const el of scene.elements) {
        if (!selectedIds.has(el.id)) continue;
        el[name] = value;
      }
    }
    render();
  }

  function updateSidebar() {
    const sb = document.getElementById("sidebar");
    if (!sb) return;

    // Get values from selected element (single) or globals
    let sel = null;
    if (selectedIds.size === 1) {
      sel = scene.elements.find(e => selectedIds.has(e.id));
    }

    const sc = sel ? (sel.strokeColor || "#1e1e2e") : strokeColor;
    const fc = sel ? (sel.fillColor || "transparent") : fillColor;
    const sw = sel ? (sel.strokeWidth || 2) : strokeWidth;
    const ss = sel ? (sel.strokeStyle || "solid") : strokeStyle;
    const fls = sel ? (sel.fillStyle || "hachure") : fillStyle;
    const rg = sel ? (sel.roughness ?? 0) : roughness;
    const rn = sel ? (sel.roundness || "sharp") : roundness;
    const op = sel ? (sel.opacity ?? 100) : opacity;
    const fs = sel ? (sel.fontSize || 16) : fontSize;
    const ff = sel ? (sel.fontFamily || "sans-serif") : fontFamily;

    // Stroke swatches
    sb.querySelectorAll("#stroke-swatches .swatch").forEach(b => {
      b.classList.toggle("active", b.dataset.color === sc);
    });
    const scp = sb.querySelector("#stroke-color-picker");
    if (sc !== "transparent") scp.value = sc;

    // Fill swatches
    sb.querySelectorAll("#fill-swatches .swatch").forEach(b => {
      b.classList.toggle("active", b.dataset.color === fc);
    });
    const fcp = sb.querySelector("#fill-color-picker");
    if (fc && fc !== "transparent") fcp.value = fc;

    // Stroke width
    sb.querySelectorAll("#sw-btns .sb-btn").forEach(b => {
      b.classList.toggle("active", parseInt(b.dataset.val) === sw);
    });

    // Stroke style
    sb.querySelectorAll("#ss-btns .sb-btn").forEach(b => {
      b.classList.toggle("active", b.dataset.val === ss);
    });

    // Fill style
    sb.querySelectorAll("#fs-fill-btns .sb-btn").forEach(b => {
      b.classList.toggle("active", b.dataset.val === fls);
    });

    // Roughness
    sb.querySelectorAll("#rg-btns .sb-btn").forEach(b => {
      b.classList.toggle("active", parseInt(b.dataset.val) === rg);
    });

    // Roundness
    sb.querySelectorAll("#rn-btns .sb-btn").forEach(b => {
      b.classList.toggle("active", b.dataset.val === rn);
    });

    // Opacity
    sb.querySelector("#opacity-slider").value = op;
    sb.querySelector("#opacity-val").textContent = op;

    // Font section — visible for text tool, text elements, or any shape (for label text)
    const fontSec = document.getElementById("font-section");
    const showFont = activeTool === "text" || (sel && (sel.type === "text" || sel.type === "rect" || sel.type === "diamond" || sel.type === "ellipse" || sel.text));
    fontSec.style.display = showFont ? "" : "none";
    if (showFont) {
      const ta = sel ? (sel.textAlign || "center") : textAlign;
      sb.querySelectorAll("#ff-btns .sb-btn").forEach(b => {
        b.classList.toggle("active", b.dataset.val === ff);
      });
      sb.querySelectorAll("#fs-btns .sb-btn").forEach(b => {
        b.classList.toggle("active", parseInt(b.dataset.val) === fs);
      });
      sb.querySelectorAll("#ta-btns .sb-btn").forEach(b => {
        b.classList.toggle("active", b.dataset.val === ta);
      });
    }

    // Angle section — visible when an element is selected
    const angleSec = document.getElementById("angle-section");
    angleSec.style.display = sel ? "" : "none";
    if (sel) {
      const deg = Math.round((sel.angle || 0) * 180 / Math.PI);
      sb.querySelector("#angle-slider").value = deg;
      sb.querySelector("#angle-val").textContent = deg + "\u00B0";
    }

    // Hide irrelevant sections for eraser/image
    const isEraserNoSel = activeTool === "eraser" && !sel;
    const isImageTool = activeTool === "image" || (sel && sel.type === "image");
    const hideStrokeFill = isEraserNoSel || isImageTool;

    for (const id of ["stroke-swatches", "fill-swatches", "sw-btns", "ss-btns", "rg-btns", "rn-btns"]) {
      const section = sb.querySelector("#" + id);
      if (section) section.closest(".sb-section").style.display = hideStrokeFill ? "none" : "";
    }
  }

  // ── Layer operations ──────────────────────────────────────────────────────
  function layerAction(action) {
    if (selectedIds.size !== 1) return;
    const id = [...selectedIds][0];
    const idx = scene.elements.findIndex(e => e.id === id);
    if (idx === -1) return;
    snapshot();
    const [moved] = scene.elements.splice(idx, 1);
    switch (action) {
      case "to-back": scene.elements.unshift(moved); break;
      case "backward": scene.elements.splice(Math.max(0, idx - 1), 0, moved); break;
      case "forward": scene.elements.splice(Math.min(scene.elements.length, idx + 1), 0, moved); break;
      case "to-front": scene.elements.push(moved); break;
    }
    render();
  }

  // ── Duplicate ─────────────────────────────────────────────────────────────
  function duplicateSelected() {
    if (!selectedIds.size) return;
    snapshot();
    const newIds = new Set();
    for (const el of [...scene.elements]) {
      if (!selectedIds.has(el.id)) continue;
      const clone = JSON.parse(JSON.stringify(el));
      clone.id = uid();
      if (clone.pts) { clone.pts = clone.pts.map(p => ({ x: p.x + 10, y: p.y + 10 })); }
      else {
        if (clone.x !== undefined) { clone.x += 10; clone.y += 10; }
        if (clone.x2 !== undefined) { clone.x2 += 10; clone.y2 += 10; }
      }
      scene.elements.push(clone);
      newIds.add(clone.id);
    }
    selectedIds = newIds;
    render();
  }

  // ── Copy / Paste / Cut ──────────────────────────────────────────────────
  function copySelected() {
    if (!selectedIds.size) return;
    clipboardElements = scene.elements
      .filter(el => selectedIds.has(el.id))
      .map(el => JSON.parse(JSON.stringify(el)));
  }

  function pasteClipboard() {
    if (!clipboardElements.length) return;
    snapshot();
    const newIds = new Set();
    for (const el of clipboardElements) {
      const clone = JSON.parse(JSON.stringify(el));
      clone.id = uid();
      if (clone.x !== undefined) { clone.x += 20; clone.y += 20; }
      if (clone.x2 !== undefined) { clone.x2 += 20; clone.y2 += 20; }
      if (clone.pts) { clone.pts = clone.pts.map(p => ({ x: p.x + 20, y: p.y + 20 })); }
      scene.elements.push(clone);
      newIds.add(clone.id);
    }
    // Update clipboard to offset again on next paste
    clipboardElements = clipboardElements.map(el => {
      const c = JSON.parse(JSON.stringify(el));
      if (c.x !== undefined) { c.x += 20; c.y += 20; }
      if (c.x2 !== undefined) { c.x2 += 20; c.y2 += 20; }
      if (c.pts) { c.pts = c.pts.map(p => ({ x: p.x + 20, y: p.y + 20 })); }
      return c;
    });
    selectedIds = newIds;
    render();
  }

  function cutSelected() {
    copySelected();
    deleteSelected();
  }

  function selectAll() {
    selectedIds = new Set(scene.elements.map(el => el.id));
    render();
  }

  // ── Export PNG ──────────────────────────────────────────────────────────
  function exportPNG() {
    if (!scene.elements.length) return;
    const pad = 20;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const el of scene.elements) {
      const bb = getBBox(el);
      minX = Math.min(minX, bb.x);
      minY = Math.min(minY, bb.y);
      maxX = Math.max(maxX, bb.x + bb.w);
      maxY = Math.max(maxY, bb.y + bb.h);
    }
    const w = maxX - minX + pad * 2;
    const h = maxY - minY + pad * 2;
    const offCanvas = document.createElement("canvas");
    const dpr = window.devicePixelRatio || 1;
    offCanvas.width = w * dpr;
    offCanvas.height = h * dpr;
    const offCtx = offCanvas.getContext("2d");
    offCtx.scale(dpr, dpr);
    // White background
    offCtx.fillStyle = darkMode ? "#1a1a2e" : "#ffffff";
    offCtx.fillRect(0, 0, w, h);
    offCtx.translate(-minX + pad, -minY + pad);
    for (const el of scene.elements) {
      drawElement(offCtx, el);
    }
    offCanvas.toBlob(blob => {
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = (title || "drawing") + ".png";
      a.click();
      URL.revokeObjectURL(url);
    }, "image/png");
  }

  // ── Export SVG ──────────────────────────────────────────────────────────
  function exportSVG() {
    if (!scene.elements.length) return;
    const pad = 20;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const el of scene.elements) {
      const bb = getBBox(el);
      minX = Math.min(minX, bb.x);
      minY = Math.min(minY, bb.y);
      maxX = Math.max(maxX, bb.x + bb.w);
      maxY = Math.max(maxY, bb.y + bb.h);
    }
    const w = maxX - minX + pad * 2;
    const h = maxY - minY + pad * 2;
    const ox = -minX + pad;
    const oy = -minY + pad;

    let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">\n`;
    svg += `<rect width="${w}" height="${h}" fill="${darkMode ? '#1a1a2e' : '#ffffff'}"/>\n`;
    svg += `<g transform="translate(${ox},${oy})">\n`;

    for (const el of scene.elements) {
      const sc = el.strokeColor || "#1e1e2e";
      const fc = el.fillColor || "transparent";
      const sw = el.strokeWidth || 2;
      const op = (el.opacity ?? 100) / 100;
      const angle = el.angle || 0;
      const dashArray = el.strokeStyle === "dashed" ? `${sw*4},${sw*3}` : el.strokeStyle === "dotted" ? `${sw*0.5},${sw*2.5}` : "";
      const dash = dashArray ? ` stroke-dasharray="${dashArray}"` : "";
      const rot = angle ? (() => { const c = getCenter(el); return ` transform="rotate(${angle*180/Math.PI},${c.x},${c.y})"`; })() : "";

      switch (el.type) {
        case "rect": {
          const rn = el.roundness || "sharp";
          const r = rn === "round" ? Math.min(Math.abs(el.w), Math.abs(el.h)) * 0.15 : 0;
          svg += `  <rect x="${el.x}" y="${el.y}" width="${el.w}" height="${el.h}" rx="${r}" fill="${fc}" stroke="${sc}" stroke-width="${sw}" opacity="${op}"${dash}${rot}/>\n`;
          if (el.text) {
            const bb = getBBox(el);
            svg += `  <text x="${bb.x+bb.w/2}" y="${bb.y+bb.h/2}" text-anchor="middle" dominant-baseline="central" font-size="${el.fontSize||16}" font-family="${fontCSS(el.fontFamily)}" fill="${sc}" opacity="${op}"${rot}>${escHtml(el.text)}</text>\n`;
          }
          break;
        }
        case "diamond": {
          const dcx = el.x + el.w/2, dcy = el.y + el.h/2;
          svg += `  <polygon points="${dcx},${el.y} ${el.x+el.w},${dcy} ${dcx},${el.y+el.h} ${el.x},${dcy}" fill="${fc}" stroke="${sc}" stroke-width="${sw}" opacity="${op}"${dash}${rot}/>\n`;
          if (el.text) {
            svg += `  <text x="${dcx}" y="${dcy}" text-anchor="middle" dominant-baseline="central" font-size="${el.fontSize||16}" font-family="${fontCSS(el.fontFamily)}" fill="${sc}" opacity="${op}"${rot}>${escHtml(el.text)}</text>\n`;
          }
          break;
        }
        case "ellipse": {
          const cx = el.x + el.w/2, cy = el.y + el.h/2;
          svg += `  <ellipse cx="${cx}" cy="${cy}" rx="${Math.abs(el.w/2)}" ry="${Math.abs(el.h/2)}" fill="${fc}" stroke="${sc}" stroke-width="${sw}" opacity="${op}"${dash}${rot}/>\n`;
          if (el.text) {
            svg += `  <text x="${cx}" y="${cy}" text-anchor="middle" dominant-baseline="central" font-size="${el.fontSize||16}" font-family="${fontCSS(el.fontFamily)}" fill="${sc}" opacity="${op}"${rot}>${escHtml(el.text)}</text>\n`;
          }
          break;
        }
        case "line":
          if (el.pts && el.pts.length > 1) {
            let d = `M${el.pts[0].x},${el.pts[0].y}`;
            for (let i = 1; i < el.pts.length; i++) d += ` L${el.pts[i].x},${el.pts[i].y}`;
            svg += `  <polyline points="${el.pts.map(p=>p.x+","+p.y).join(" ")}" fill="none" stroke="${sc}" stroke-width="${sw}" opacity="${op}"${dash}${rot}/>\n`;
          } else {
            svg += `  <line x1="${el.x}" y1="${el.y}" x2="${el.x2}" y2="${el.y2}" stroke="${sc}" stroke-width="${sw}" opacity="${op}"${dash}${rot}/>\n`;
          }
          break;
        case "arrow": {
          let endX, endY, prevX, prevY;
          if (el.pts && el.pts.length > 1) {
            let d = el.pts.map(p=>p.x+","+p.y).join(" ");
            svg += `  <polyline points="${d}" fill="none" stroke="${sc}" stroke-width="${sw}" opacity="${op}"${dash}${rot}/>\n`;
            endX = el.pts[el.pts.length-1].x; endY = el.pts[el.pts.length-1].y;
            prevX = el.pts[el.pts.length-2].x; prevY = el.pts[el.pts.length-2].y;
          } else {
            svg += `  <line x1="${el.x}" y1="${el.y}" x2="${el.x2}" y2="${el.y2}" stroke="${sc}" stroke-width="${sw}" opacity="${op}"${dash}${rot}/>\n`;
            endX = el.x2; endY = el.y2; prevX = el.x; prevY = el.y;
          }
          const dx = endX - prevX, dy = endY - prevY;
          const len = Math.hypot(dx, dy);
          const ux = len ? dx/len : 0, uy = len ? dy/len : 0;
          const headLen = Math.min(12, len * 0.3);
          const ax1 = endX - headLen * ux + headLen * 0.4 * uy;
          const ay1 = endY - headLen * uy - headLen * 0.4 * ux;
          const ax2 = endX - headLen * ux - headLen * 0.4 * uy;
          const ay2 = endY - headLen * uy + headLen * 0.4 * ux;
          svg += `  <polygon points="${endX},${endY} ${ax1},${ay1} ${ax2},${ay2}" fill="${sc}" opacity="${op}"${rot}/>\n`;
          break;
        }
        case "pencil":
          if (el.pts && el.pts.length > 1) {
            let d = `M${el.pts[0].x},${el.pts[0].y}`;
            for (let i = 1; i < el.pts.length; i++) d += ` L${el.pts[i].x},${el.pts[i].y}`;
            svg += `  <path d="${d}" fill="none" stroke="${sc}" stroke-width="${sw}" opacity="${op}" stroke-linecap="round" stroke-linejoin="round"${dash}${rot}/>\n`;
          }
          break;
        case "text": {
          const fs = el.fontSize || 16;
          const lines = (el.text || "").split("\n");
          const lh = fs * 1.3;
          lines.forEach((line, i) => {
            svg += `  <text x="${el.x}" y="${el.y + (i + 0.8) * lh}" font-size="${fs}" fill="${sc}" opacity="${op}" font-family="${fontCSS(el.fontFamily)}"${rot}>${escHtml(line)}</text>\n`;
          });
          break;
        }
        case "image":
          if (el.src) {
            svg += `  <image href="${el.src}" x="${el.x}" y="${el.y}" width="${el.w}" height="${el.h}" opacity="${op}"${rot}/>\n`;
          }
          break;
      }
    }
    svg += `</g>\n</svg>`;

    const blob = new Blob([svg], { type: "image/svg+xml" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = (title || "drawing") + ".svg";
    a.click();
    URL.revokeObjectURL(url);
  }

  // ── Dark mode ──────────────────────────────────────────────────────────
  function toggleDarkMode() {
    darkMode = !darkMode;
    localStorage.setItem("godraw-dark", darkMode);
    darkModeOverride = true;
    sessionStorage.setItem(darkOverrideKey, "true");
    applyDarkMode();
    render();
  }

  function applyDarkMode() {
    document.documentElement.classList.toggle("godraw-dark", darkMode);
    const btn = document.getElementById("btn-dark-mode");
    if (btn) btn.innerHTML = darkMode ? '\u2600\uFE0F' : '\uD83C\uDF19';
  }

  // ── Copy link ─────────────────────────────────────────────────────────────
  function copyLink() {
    const url = window.location.origin + `${CFG.basePath}/${CFG.id}`;
    navigator.clipboard.writeText(url).then(() => {
      const status = document.getElementById("save-status");
      if (status) { status.textContent = "Link copied!"; setTimeout(() => status.textContent = "", 2000); }
    }).catch(() => {});
  }

  // ── Element creation ──────────────────────────────────────────────────────
  function makeElement(wx, wy) {
    const base = {
      id: uid(),
      type: activeTool,
      strokeColor,
      fillColor,
      fillStyle,
      strokeWidth,
      strokeStyle,
      roughness,
      roundness,
      opacity,
      angle: 0,
    };
    switch (activeTool) {
      case "rect":
      case "diamond":
      case "ellipse":
        return { ...base, x: wx, y: wy, w: 0, h: 0 };
      case "line":
      case "arrow":
        return { ...base, x: wx, y: wy, x2: wx, y2: wy };
      case "pencil":
        return { ...base, pts: [{ x: wx, y: wy }] };
      default:
        return null;
    }
  }

  function updateElement(el, wx, wy) {
    if (!el) return;
    switch (el.type) {
      case "rect":
      case "diamond":
      case "ellipse":
      case "image":
        el.w = wx - startX; el.h = wy - startY;
        break;
      case "line":
      case "arrow":
        el.x2 = wx; el.y2 = wy;
        break;
    }
  }

  function moveElement(el, dx, dy) {
    switch (el.type) {
      case "rect": case "diamond": case "ellipse": case "text": case "image":
        el.x += dx; el.y += dy; break;
      case "line": case "arrow":
        if (el.pts) { el.pts = el.pts.map(p => ({ x: p.x + dx, y: p.y + dy })); }
        else { el.x += dx; el.y += dy; el.x2 += dx; el.y2 += dy; }
        if (el.cp) { el.cp = { x: el.cp.x + dx, y: el.cp.y + dy }; }
        break;
      case "pencil":
        el.pts = el.pts.map(p => ({ x: p.x + dx, y: p.y + dy })); break;
    }
  }

  function deleteSelected() {
    if (!selectedIds.size) return;
    snapshot();
    scene.elements = scene.elements.filter(el => !selectedIds.has(el.id));
    selectedIds.clear();
    render();
  }

  // ── Text input overlay ────────────────────────────────────────────────────
  function startTextInput(wx, wy) {
    const sx = wx * vp.scale + vp.x;
    const sy = wy * vp.scale + vp.y;
    const wrap = canvas.parentElement;

    textInput = document.createElement("textarea");
    textInput.style.cssText = `
      position:absolute; left:${sx}px; top:${sy}px;
      margin:0; padding:0; border:none; outline:none; resize:none;
      background:transparent; overflow:hidden;
      min-width:1ch; min-height:${fontSize * vp.scale * 1.3}px;
      font-size:${fontSize * vp.scale}px;
      font-family:${fontCSS(fontFamily)};
      color:${strokeColor};
      line-height:1.3; z-index:10;
      white-space:pre; word-break:keep-all;
      box-shadow:0 0 0 1.5px #3b82f6;
      border-radius:2px;
    `;
    textInput.dataset.wx = wx;
    textInput.dataset.wy = wy;
    textInput.dataset.fs = fontSize;
    textInput.dataset.textFontFamily = fontFamily;
    wrap.appendChild(textInput);
    requestAnimationFrame(() => textInput && textInput.focus());

    textInput.addEventListener("keydown", e => {
      if (e.key === "Escape") { commitTextInput(); }
    });
    textInput.addEventListener("blur", () => commitTextInput());
    textInput.addEventListener("input", () => render());
  }

  function startTextInputOnElement(el) {
    // Edit existing text element — store original ID to update in place
    scene.elements = scene.elements.filter(e => e.id !== el.id);
    render();
    const sx = el.x * vp.scale + vp.x;
    const sy = el.y * vp.scale + vp.y;
    const wrap = canvas.parentElement;
    textInput = document.createElement("textarea");
    textInput.value = el.text || "";
    textInput.style.cssText = `
      position:absolute; left:${sx}px; top:${sy}px;
      margin:0; padding:0; border:none; outline:none; resize:none;
      background:transparent; overflow:hidden;
      min-width:1ch; min-height:${(el.fontSize || 16) * vp.scale * 1.3}px;
      font-size:${(el.fontSize || 16) * vp.scale}px;
      font-family:${fontCSS(el.fontFamily)};
      color:${el.strokeColor || strokeColor};
      line-height:1.3; z-index:10;
      white-space:pre; word-break:keep-all;
      box-shadow:0 0 0 1.5px #3b82f6;
      border-radius:2px;
    `;
    textInput.dataset.wx = el.x;
    textInput.dataset.wy = el.y;
    textInput.dataset.fs = el.fontSize || fontSize;
    textInput.dataset.textElementId = el.id;
    textInput.dataset.textStrokeColor = el.strokeColor || strokeColor;
    textInput.dataset.textOpacity = el.opacity != null ? el.opacity : opacity;
    textInput.dataset.textFontFamily = el.fontFamily || fontFamily;
    wrap.appendChild(textInput);
    requestAnimationFrame(() => textInput && textInput.focus());
    textInput.addEventListener("keydown", e => { if (e.key === "Escape") commitTextInput(); });
    textInput.addEventListener("blur", () => commitTextInput());
  }

  function startTextInputOnShape(el) {
    // Edit text label inside a shape. We keep the canvas rendering the live
    // text and overlay a transparent textarea so what the user sees IS the
    // final render (Excalidraw style — no visual shift on commit).
    el._savedText = el.text || "";
    el._editing = true;
    el.text = el._savedText;
    render();
    const bb = getBBox(el);
    const wrap = canvas.parentElement;
    const fs = el.fontSize || fontSize;
    const ff = el.fontFamily || fontFamily;
    const cssM = getCssFontMetrics(ff, fs);
    const lineHeight = cssM.lineHeight;
    // Align the textarea so its first-line baseline lines up with the canvas
    // baseline we draw from in drawShapeText.
    const canvasBaselineWorld = bb.y + bb.h / 2 - lineHeight / 2 + cssM.baseline;
    const canvasBaselineScreen = canvasBaselineWorld * vp.scale + vp.y;
    const taTop = canvasBaselineScreen - cssM.baseline * vp.scale;
    const taLeft = (bb.x + bb.w / 2) * vp.scale + vp.x;
    textInput = document.createElement("textarea");
    textInput.value = el._savedText;
    textInput.style.cssText = `
      position:absolute; left:${taLeft}px; top:${taTop}px;
      transform:translateX(-50%);
      margin:0; padding:0; border:none; outline:none; resize:none;
      background:transparent; overflow:hidden;
      min-width:1ch; height:${lineHeight * vp.scale}px;
      max-width:${Math.max(60, Math.abs(bb.w) * vp.scale - 16)}px;
      font-size:${fs * vp.scale}px;
      font-family:${fontCSS(ff)};
      color:transparent; caret-color:${el.strokeColor || strokeColor};
      line-height:1.3; text-align:center; z-index:10;
      white-space:pre; word-break:keep-all;
      vertical-align:top; box-sizing:content-box;
    `;
    textInput.dataset.wx = bb.x + bb.w / 2;
    textInput.dataset.wy = bb.y + bb.h / 2;
    textInput.dataset.fs = fs;
    textInput.dataset.shapeId = el.id;
    wrap.appendChild(textInput);
    requestAnimationFrame(() => textInput && textInput.focus());
    textInput.addEventListener("keydown", e => { if (e.key === "Escape") commitTextInput(); });
    textInput.addEventListener("blur", () => commitTextInput());
    textInput.addEventListener("input", () => {
      el.text = textInput.value;
      // Grow textarea vertically as lines are added.
      const newLineCount = (textInput.value.match(/\n/g) || []).length + 1;
      textInput.style.height = (lineHeight * vp.scale * newLineCount) + "px";
      render();
    });
  }

  function commitTextInput() {
    if (!textInput) return;
    const ti = textInput;
    textInput = null;  // null FIRST — prevents re-entrance via synchronous blur
    const text = ti.value.trim();
    const wx = parseFloat(ti.dataset.wx);
    const wy = parseFloat(ti.dataset.wy);
    const fs = parseInt(ti.dataset.fs);
    const shapeId = ti.dataset.shapeId || "";
    ti.remove();

    // Shape label editing — update the shape's text property
    if (shapeId) {
      const shape = scene.elements.find(e => e.id === shapeId);
      if (shape) {
        snapshot();
        shape.text = text;
        shape.fontSize = fs;
        shape.fontFamily = shape.fontFamily || fontFamily;
        delete shape._savedText;
        delete shape._editing;
      }
      render();
      return;
    }

    // Standalone text — discard if empty
    if (!text) { render(); return; }
    snapshot();
    // Measure width (rough)
    const ff = ti.dataset.textFontFamily || fontFamily;
    ctx.font = `${fs}px ${fontCSS(ff)}`;
    const lines = text.split("\n");
    const maxW = Math.max(...lines.map(l => ctx.measureText(l).width));
    // Reuse original ID when editing existing text element
    const existingId = ti.dataset.textElementId || "";
    scene.elements.push({
      id: existingId || uid(), type: "text",
      x: wx, y: wy,
      w: maxW, h: lines.length * fs * 1.3,
      text, fontSize: fs, fontFamily: ff, textAlign,
      strokeColor: existingId ? (ti.dataset.textStrokeColor || strokeColor) : strokeColor,
      opacity: existingId ? parseFloat(ti.dataset.textOpacity) : opacity,
    });
    render();
  }

  // ── Save ──────────────────────────────────────────────────────────────────
  async function saveDrawing() {
    const status = document.getElementById("save-status");
    if (status) status.textContent = "Saving\u2026";
    try {
      if (CFG.storage === "local") {
        localStorage.setItem("godraw-local-scene", JSON.stringify({ title, scene }));
      } else {
        const res = await fetch(`${CFG.basePath}/${CFG.id}/save`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ title, scene }),
        });
        if (!res.ok) throw new Error(await res.text());
      }
      if (status) { status.textContent = "Saved \u2713"; setTimeout(() => { status.textContent = ""; }, 2000); }
    } catch (err) {
      if (status) status.textContent = "Error: " + err.message;
    }
  }

  // ── Load ──────────────────────────────────────────────────────────────────
  async function loadDrawing() {
    try {
      var data;
      if (CFG.storage === "local") {
        var raw = localStorage.getItem("godraw-local-scene");
        data = raw ? JSON.parse(raw) : { title: "Untitled", scene: { version: 1, elements: [] } };
      } else {
        const res = await fetch(`${CFG.basePath}/${CFG.id}/data`);
        if (!res.ok) throw new Error("HTTP " + res.status);
        data = await res.json();
      }
      title = data.title || "Untitled";
      scene = typeof data.scene === "string" ? JSON.parse(data.scene) : (data.scene || { version: 1, elements: [] });
      if (IS_EDIT) {
        const ti = document.getElementById("title-input");
        if (ti) ti.value = title;
      }
      render();
    } catch (err) {
      console.error("go-draw: failed to load drawing", err);
    }
  }

  // ── Zoom to fit ────────────────────────────────────────────────────────────
  function zoomToFit() {
    if (!scene.elements.length) {
      vp.x = canvas.width / 2;
      vp.y = canvas.height / 2;
      vp.scale = 1;
      return;
    }
    var minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (var i = 0; i < scene.elements.length; i++) {
      var bb = getBBox(scene.elements[i]);
      if (bb.x < minX) minX = bb.x;
      if (bb.y < minY) minY = bb.y;
      if (bb.x + bb.w > maxX) maxX = bb.x + bb.w;
      if (bb.y + bb.h > maxY) maxY = bb.y + bb.h;
    }
    var contentW = maxX - minX;
    var contentH = maxY - minY;
    if (contentW < 1) contentW = 1;
    if (contentH < 1) contentH = 1;
    var pad = 20;
    var scaleX = (canvas.width - pad * 2) / contentW;
    var scaleY = (canvas.height - pad * 2) / contentH;
    // On narrow canvases (mobile embeds) prioritise width-fit so text stays
    // readable. The user can pan/pinch to see content that overflows
    // vertically. Desktop still fits both dimensions.
    var isNarrow = canvas.width < 600;
    if (isNarrow) {
      vp.scale = Math.min(scaleX, 3);
    } else {
      vp.scale = Math.min(scaleX, scaleY, 2);
    }
    var cx = (minX + maxX) / 2;
    var cy = (minY + maxY) / 2;
    vp.x = canvas.width / 2 - cx * vp.scale;
    if (isNarrow) {
      // Top-align content with some padding so the first row is visible
      // without panning.
      vp.y = pad - minY * vp.scale;
    } else {
      vp.y = canvas.height / 2 - cy * vp.scale;
    }
  }

  // Center on content at a given scale
  function centerOnContent(scale) {
    vp.scale = scale;
    if (scene.elements.length) {
      var minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
      for (var i = 0; i < scene.elements.length; i++) {
        var bb = getBBox(scene.elements[i]);
        if (bb.x < minX) minX = bb.x;
        if (bb.y < minY) minY = bb.y;
        if (bb.x + bb.w > maxX) maxX = bb.x + bb.w;
        if (bb.y + bb.h > maxY) maxY = bb.y + bb.h;
      }
      var cx = (minX + maxX) / 2;
      var cy = (minY + maxY) / 2;
      vp.x = canvas.width / 2 - cx * vp.scale;
      vp.y = canvas.height / 2 - cy * vp.scale;
    }
  }

  // Parse zoom query param: "fit", "1.5", "150%", "50%" etc.
  function getZoomParam() {
    try {
      var params = new URLSearchParams(window.location.search);
      var z = params.get("zoom");
      if (!z) return null;
      if (z === "fit") return "fit";
      if (z.endsWith("%")) z = z.slice(0, -1);
      var n = parseFloat(z);
      if (!isNaN(n) && n > 0) {
        return n > 10 ? n / 100 : n;
      }
      return null;
    } catch (_) { return null; }
  }

  // ── Modal helpers ─────────────────────────────────────────────────────────
  function openModal(html) {
    const overlay = document.createElement("div");
    overlay.className = "godraw-modal-overlay";
    const modal = document.createElement("div");
    modal.className = "godraw-modal";
    modal.innerHTML = html;
    overlay.appendChild(modal);
    document.body.appendChild(overlay);
    overlay.addEventListener("click", (e) => { if (e.target === overlay) closeModal(overlay); });
    return { overlay, modal };
  }

  function closeModal(overlay) {
    if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
  }

  // ── Share dialog ───────────────────────────────────────────────────────
  function openShareDialog() {
    // When the canvas is running in local-storage mode (standalone root
    // page), there is no server-side drawing id yet, so share/view/embed
    // links wouldn't resolve. Offer a "Publish to share" flow that uploads
    // the current scene to the server and redirects to the real edit URL.
    if (CFG.storage === "local") {
      const { overlay, modal } = openModal(`
        <h3>Publish to share</h3>
        <p style="font-size:.85rem;color:#666;margin:0 0 12px;">
          This drawing lives only in your browser right now. Publish it to the
          server to get a shareable link, a collaboration link, and an embed
          code.
        </p>
        <div class="modal-actions">
          <button class="modal-btn modal-btn-secondary" id="publish-cancel">Cancel</button>
          <button class="modal-btn modal-btn-primary" id="publish-go">\uD83D\uDCE4 Publish &amp; share</button>
        </div>
      `);
      modal.querySelector("#publish-cancel").addEventListener("click", () => closeModal(overlay));
      modal.querySelector("#publish-go").addEventListener("click", async () => {
        const btn = modal.querySelector("#publish-go");
        btn.disabled = true;
        btn.textContent = "Publishing\u2026";
        try {
